export enum GenerationStatus {
  IDLE = 'idle',
  GENERATING_TEXT = 'generating_text',
  COMPLETED = 'completed',
  ERROR = 'error',
}

export interface EbookData {
  title: string;
  subtitle: string;
  content: string; // The full raw markdown/text content
}

export interface ImageRequest {
  id: string;
  prompt: string;
  url?: string;
  status: 'pending' | 'loading' | 'success' | 'error';
}

export type SectionType = 'cover' | 'toc' | 'chapter' | 'summary' | 'intro';

import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// The specific persona instructions from the user prompt
const EBOOK_CREATOR_SYSTEM_INSTRUCTION = `
You are a Professional Ebook Creator AI who writes premium, sell-ready ebooks.

Output Structure Rules:
1. Follow the exact format:
   [EBOOK TITLE]
   Subtitle
   <<IMAGE_PROMPT: Describe the cover image>>
   Table of Contents
   CHAPTER 1 - Title
   <<IMAGE_PROMPT: Describe chapter 1 visual>>
   (Content with Bullet points, Examples, Step-by-step frameworks, Action steps)
   ... (Continue for Minimum 5-7 chapters for brevity in this demo, but aim for quality)
   Final Summary Page
   Bonus Resources & Tools
   ✔ EBOOK COMPLETE.

2. Formatting:
   - Use Markdown for bolding, lists, and headers.
   - Use '##' for Chapter Titles.
   - Use '###' for Subsections.
   - CRITICAL: Whenever you need an image (cover or chapter header), strictly use this tag on its own line:
     <<IMAGE_PROMPT: Detailed description of the image>>
   - Do NOT use standard markdown image syntax like ![alt](url). Use the custom tag above.

3. Writing Style:
   - Clean, modern, premium tone.
   - No fluff, high-value content only.
   - Author-level quality.
`;

export const streamEbookContent = async (
  topic: string,
  details: string,
  onChunk: (text: string) => void
) => {
  try {
    const prompt = `Topic: ${topic}\nDetails: ${details}\n\nStart creating the ebook now following the strict format.`;

    const response = await ai.models.generateContentStream({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: EBOOK_CREATOR_SYSTEM_INSTRUCTION,
        temperature: 0.7, // Slightly creative but structured
      }
    });

    for await (const chunk of response) {
      if (chunk.text) {
        onChunk(chunk.text);
      }
    }
  } catch (error) {
    console.error("Error generating ebook text:", error);
    throw error;
  }
};

export const generateEbookImage = async (prompt: string): Promise<string> => {
  try {
    // Using gemini-2.5-flash-image for speed and efficiency as per guidelines
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: prompt }]
      },
      config: {
         imageConfig: {
           aspectRatio: "16:9",
         }
      }
    });

    // Extract image
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data found in response");
  } catch (error) {
    console.error("Error generating image:", error);
    // Return a fallback placeholder if generation fails to avoid breaking UI
    return `https://picsum.photos/seed/${encodeURIComponent(prompt)}/800/450`; 
  }
};

import React, { useEffect, useState, useRef } from 'react';
import { generateEbookImage } from '../services/gemini';
import { Image, Loader2, RefreshCw } from 'lucide-react';

interface ImageRendererProps {
  prompt: string;
  className?: string;
}

export const ImageRenderer: React.FC<ImageRendererProps> = ({ prompt, className = "" }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);
  const hasFetched = useRef(false);

  const fetchImage = async () => {
    if (!prompt) return;
    setLoading(true);
    setError(false);
    try {
      const url = await generateEbookImage(prompt);
      setImageUrl(url);
    } catch (err) {
      console.error(err);
      setError(true);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    // Only fetch once when the component mounts and receives a prompt
    if (prompt && !hasFetched.current) {
      hasFetched.current = true;
      fetchImage();
    }
  }, [prompt]);

  if (loading) {
    return (
      <div className={`w-full aspect-video bg-brand-200 rounded-lg flex flex-col items-center justify-center text-brand-800 animate-pulse ${className}`}>
        <Loader2 className="w-8 h-8 animate-spin mb-2" />
        <span className="text-sm font-medium">Visualizing: {prompt.slice(0, 30)}...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className={`w-full aspect-video bg-red-50 rounded-lg flex flex-col items-center justify-center text-red-500 border border-red-200 ${className}`}>
        <p className="text-sm mb-2">Failed to generate image</p>
        <button 
          onClick={fetchImage}
          className="flex items-center gap-2 px-3 py-1 bg-white border border-red-200 rounded-md hover:bg-red-50 transition-colors shadow-sm"
        >
          <RefreshCw className="w-4 h-4" /> Retry
        </button>
      </div>
    );
  }

  if (imageUrl) {
    return (
      <div className={`relative group w-full rounded-lg overflow-hidden shadow-md my-6 ${className}`}>
        <img 
          src={imageUrl} 
          alt={prompt} 
          className="w-full h-full object-cover transition-transform duration-700 hover:scale-105" 
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-end p-4">
          <p className="text-white text-xs font-light truncate w-full">{prompt}</p>
        </div>
      </div>
    );
  }

  return null;
};

import React, { useMemo } from 'react';
import { ImageRenderer } from './ImageRenderer';
import { Download, BookOpen, Menu } from 'lucide-react';

interface EbookReaderProps {
  content: string;
  isGenerating: boolean;
}

// Helper to parse content into blocks (text vs image prompts)
const parseContent = (text: string) => {
  const lines = text.split('\n');
  const blocks: { type: 'text' | 'image' | 'title'; content: string; id: string }[] = [];

  let currentTextBlock = '';
  let titleFound = false;

  lines.forEach((line, index) => {
    // Check for Image Tag
    const imageMatch = line.match(/<<IMAGE_PROMPT:\s*(.*?)>>/);

    if (imageMatch) {
      // Push accumulated text
      if (currentTextBlock.trim()) {
        blocks.push({ type: 'text', content: currentTextBlock, id: `txt-${index}` });
        currentTextBlock = '';
      }
      // Push image block
      blocks.push({ type: 'image', content: imageMatch[1], id: `img-${index}` });
    } 
    // Check for Main Title (Simple heuristic: First generic text line or [EBOOK TITLE])
    else if (!titleFound && (line.includes('[EBOOK TITLE]') || (line.trim().length > 0 && index < 5 && !line.startsWith('Topic:')))) {
       // Push accumulated text
       if (currentTextBlock.trim()) {
        blocks.push({ type: 'text', content: currentTextBlock, id: `txt-${index}-prev` });
        currentTextBlock = '';
      }
      blocks.push({ type: 'title', content: line.replace('[EBOOK TITLE]', '').trim(), id: `title-${index}` });
      titleFound = true;
    }
    else {
      currentTextBlock += line + '\n';
    }
  });

  if (currentTextBlock.trim()) {
    blocks.push({ type: 'text', content: currentTextBlock, id: `txt-end` });
  }

  return blocks;
};

export const EbookReader: React.FC<EbookReaderProps> = ({ content, isGenerating }) => {
  const blocks = useMemo(() => parseContent(content), [content]);

  // Handle PDF Print
  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="flex flex-col h-screen bg-brand-50 overflow-hidden">
      {/* Top Bar */}
      <div className="h-16 bg-white border-b border-brand-200 flex items-center justify-between px-6 shadow-sm z-10 print-hide">
        <div className="flex items-center gap-2 text-brand-800">
          <BookOpen className="w-6 h-6" />
          <span className="font-serif font-bold text-lg tracking-tight">ProBook AI</span>
        </div>

        <div className="flex items-center gap-4">
            {isGenerating && (
                <div className="flex items-center gap-2 text-brand-600 text-sm font-medium animate-pulse">
                    <div className="w-2 h-2 rounded-full bg-brand-600"></div>
                    Writing...
                </div>
            )}
            <button 
                onClick={handlePrint}
                disabled={isGenerating && content.length < 100}
                className="flex items-center gap-2 px-4 py-2 bg-brand-800 text-white rounded-md hover:bg-brand-900 disabled:opacity-50 disabled:cursor-not-allowed transition-all font-medium text-sm shadow-sm"
            >
                <Download className="w-4 h-4" /> Export PDF
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-hidden relative flex">
        {/* Main Content Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-12 scroll-smooth">
          <div className="max-w-4xl mx-auto bg-white shadow-xl min-h-[calc(100vh-8rem)] p-8 md:p-16 rounded-sm print:shadow-none print:p-0">

            {blocks.map((block) => {
              if (block.type === 'title') {
                return (
                  <h1 key={block.id} className="text-4xl md:text-6xl font-serif font-black text-brand-900 mb-4 tracking-tight leading-tight border-b-4 border-brand-200 pb-8 text-center print:text-black">
                    {block.content}
                  </h1>
                );
              }

              if (block.type === 'image') {
                return (
                  <div key={block.id} className="break-inside-avoid page-break-inside-avoid">
                     <ImageRenderer prompt={block.content} />
                  </div>
                );
              }

              // Markdown-ish Rendering for Text Blocks
              return (
                <div key={block.id} className="prose prose-lg max-w-none prose-headings:font-serif prose-headings:text-brand-900 prose-p:text-gray-700 prose-p:leading-relaxed prose-li:text-gray-700 font-serif">
                    {block.content.split('\n').map((line, i) => {
                        // Simple custom markdown parser for basic formatting
                        if (line.startsWith('CHAPTER') || line.startsWith('## ')) {
                           const title = line.replace('## ', '').replace('**', '').replace('**', '');
                           return <h2 key={i} className="text-3xl font-bold mt-12 mb-6 text-brand-800 print-break">{title}</h2>; 
                        }
                        if (line.startsWith('### ')) {
                            return <h3 key={i} className="text-xl font-bold mt-8 mb-4 text-brand-700">{line.replace('### ', '')}</h3>;
                        }
                        if (line.trim().startsWith('- ')) {
                            return <li key={i} className="ml-4 list-disc pl-2 mb-2">{line.replace('- ', '')}</li>;
                        }
                        if (line.trim().length === 0) {
                            return <br key={i} />;
                        }
                        // Handle Bold text **text**
                        const parts = line.split(/(\*\*.*?\*\*)/);
                        return (
                            <p key={i} className="mb-4">
                                {parts.map((part, idx) => {
                                    if (part.startsWith('**') && part.endsWith('**')) {
                                        return <strong key={idx}>{part.slice(2, -2)}</strong>;
                                    }
                                    return part;
                                })}
                            </p>
                        );
                    })}
                </div>
              );
            })}

            {isGenerating && (
                 <div className="mt-8 flex justify-center opacity-50">
                    <span className="animate-pulse text-brand-400 text-3xl">•••</span>
                 </div>
            )}

            {!isGenerating && content.length === 0 && (
                <div className="text-center py-20 text-gray-400">
                    <p>Ready to write your masterpiece.</p>
                </div>
            )}

            {!isGenerating && content.length > 0 && (
                 <div className="mt-20 pt-10 border-t border-brand-100 text-center text-gray-400 text-sm font-sans">
                    <p>Generated by ProBook AI</p>
                 </div>
            )}

          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { streamEbookContent } from './services/gemini';
import { EbookReader } from './components/EbookReader';
import { GenerationStatus } from './types';
import { Sparkles, PenTool, BookTemplate } from 'lucide-react';

const App = () => {
  const [topic, setTopic] = useState('');
  const [details, setDetails] = useState('');
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [ebookContent, setEbookContent] = useState('');

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic) return;

    setStatus(GenerationStatus.GENERATING_TEXT);
    setEbookContent(''); // Reset

    try {
      let accumulatedText = '';
      await streamEbookContent(topic, details, (chunk) => {
        accumulatedText += chunk;
        setEbookContent(accumulatedText);
      });
      setStatus(GenerationStatus.COMPLETED);
    } catch (error) {
      console.error("Failed to generate ebook", error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  if (status === GenerationStatus.IDLE || (status === GenerationStatus.ERROR && !ebookContent)) {
    return (
      <div className="min-h-screen bg-brand-50 flex items-center justify-center p-4">
        <div className="max-w-2xl w-full bg-white rounded-xl shadow-2xl overflow-hidden border border-brand-100">
          <div className="p-8 md:p-12">
            <div className="flex items-center justify-center mb-8 text-brand-700">
               <div className="bg-brand-100 p-3 rounded-full mr-3">
                 <PenTool className="w-8 h-8" />
               </div>
               <h1 className="text-3xl font-serif font-bold text-brand-900">ProBook AI</h1>
            </div>

            <div className="text-center mb-10">
              <h2 className="text-xl font-medium text-gray-800 mb-2">Create a Premium Ebook in Minutes</h2>
              <p className="text-gray-500 font-sans">Enter your topic, and our AI will author a sell-ready book with structure, visuals, and professional content.</p>
            </div>

            <form onSubmit={handleGenerate} className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-brand-900 mb-2 uppercase tracking-wide">Ebook Topic</label>
                <input
                  type="text"
                  value={topic}
                  onChange={(e) => setTopic(e.target.value)}
                  placeholder="e.g. The Art of Minimalist Living"
                  className="w-full p-4 bg-brand-50 border border-brand-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-500 text-lg font-serif placeholder-brand-300 transition-all"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-bold text-brand-900 mb-2 uppercase tracking-wide">Target Audience & Details</label>
                <textarea
                  value={details}
                  onChange={(e) => setDetails(e.target.value)}
                  placeholder="e.g. For busy professionals who want to declutter. Tone should be calming but actionable. Include a 7-day challenge."
                  className="w-full p-4 bg-brand-50 border border-brand-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-500 font-sans h-32 resize-none placeholder-brand-300 transition-all"
                />
              </div>

              <button
                type="submit"
                className="w-full py-5 bg-brand-800 text-white rounded-lg font-bold text-lg hover:bg-brand-900 transition-transform active:scale-[0.99] shadow-lg flex items-center justify-center gap-2 group"
              >
                <Sparkles className="w-5 h-5 group-hover:text-yellow-200 transition-colors" />
                Start Writing
              </button>

              {status === GenerationStatus.ERROR && (
                <p className="text-red-500 text-center text-sm mt-4 bg-red-50 p-2 rounded">
                  Something went wrong. Please check your API key and try again.
                </p>
              )}
            </form>
          </div>
          <div className="bg-brand-100 px-8 py-4 flex justify-between items-center text-xs text-brand-800 font-medium tracking-wider uppercase">
             <span>Powered by Gemini 2.5</span>
             <span className="flex items-center gap-1"><BookTemplate className="w-3 h-3" /> Professional Format</span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <EbookReader 
      content={ebookContent} 
      isGenerating={status === GenerationStatus.GENERATING_TEXT} 
    />
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { generateEbookImage } from '../services/gemini';
import { Image as ImageIcon, Loader2, RefreshCw, Wand2 } from 'lucide-react';

interface ImageRendererProps {
  prompt: string;
  className?: string;
  isCover?: boolean;
}

export const ImageRenderer: React.FC<ImageRendererProps> = ({ prompt: initialPrompt, className = "", isCover = false }) => {
  const [prompt, setPrompt] = useState(initialPrompt);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');

  useEffect(() => {
    // Update internal prompt only if the prop changes significantly (to avoid overwriting user edits on minor re-renders if distinct)
    if (initialPrompt && initialPrompt !== prompt && status === 'idle') {
       setPrompt(initialPrompt);
    }
  }, [initialPrompt]);

  const handleGenerate = async () => {
    if (!prompt) return;
    setStatus('loading');
    try {
      const url = await generateEbookImage(prompt);
      setImageUrl(url);
      setStatus('success');
    } catch (err) {
      console.error(err);
      setStatus('error');
    }
  };

  const containerClasses = `w-full rounded-lg overflow-hidden my-8 transition-all duration-300 ${className}`;
  const aspectRatioClass = isCover ? 'aspect-[16/9]' : 'aspect-video';

  if (status === 'loading') {
    return (
      <div className={`${containerClasses} ${aspectRatioClass} bg-brand-100 flex flex-col items-center justify-center text-brand-800 animate-pulse border border-brand-200`}>
        <Loader2 className="w-10 h-10 animate-spin mb-3 text-brand-600" />
        <span className="text-sm font-medium font-serif">Creating your masterpiece...</span>
        <p className="text-xs text-brand-500 mt-2 max-w-md text-center px-4 truncate opacity-75">{prompt}</p>
      </div>
    );
  }

  if (status === 'error') {
    return (
      <div className={`${containerClasses} ${aspectRatioClass} bg-red-50 flex flex-col items-center justify-center text-red-500 border border-red-200`}>
        <p className="text-sm font-medium mb-3">Unable to generate image</p>
        <button 
          onClick={handleGenerate}
          className="flex items-center gap-2 px-4 py-2 bg-white border border-red-200 rounded-md hover:bg-red-50 transition-colors shadow-sm text-sm"
        >
          <RefreshCw className="w-4 h-4" /> Try Again
        </button>
      </div>
    );
  }

  if (status === 'success' && imageUrl) {
    return (
      <div className={`${containerClasses} relative group shadow-lg`}>
        <img 
          src={imageUrl} 
          alt={prompt} 
          className="w-full h-full object-cover" 
        />
        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center backdrop-blur-[2px]">
            <button 
                onClick={() => setStatus('idle')}
                className="bg-white/90 text-brand-900 px-5 py-2.5 rounded-full font-bold text-sm flex items-center gap-2 hover:bg-white transition-all transform hover:scale-105 shadow-xl"
            >
                <RefreshCw className="w-4 h-4" /> Regenerate
            </button>
        </div>
      </div>
    );
  }

  // IDLE State (Placeholder / Editor)
  return (
    <div className={`${containerClasses} ${aspectRatioClass} bg-brand-50 border-2 border-dashed border-brand-300 flex flex-col items-center justify-center p-6 text-center group hover:border-brand-400 transition-colors`}>
      <div className="w-12 h-12 rounded-full bg-brand-100 flex items-center justify-center mb-4 text-brand-500 group-hover:bg-brand-200 transition-colors">
        <ImageIcon className="w-6 h-6" />
      </div>

      <h3 className="font-serif font-bold text-brand-800 text-lg mb-2">
        {isCover ? 'Cover Art' : 'Section Illustration'}
      </h3>

      <div className="w-full max-w-lg relative mb-6">
        <label className="block text-xs font-bold text-brand-400 uppercase tracking-wider mb-2 text-left ml-1">
           Prompt
        </label>
        <textarea 
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            className="w-full p-3 bg-white border border-brand-200 rounded-lg text-sm text-gray-700 focus:outline-none focus:ring-2 focus:ring-brand-500 resize-none shadow-sm font-sans leading-relaxed"
            rows={isCover ? 3 : 2}
        />
      </div>

      <button 
        onClick={handleGenerate}
        className="flex items-center gap-2 px-6 py-2.5 bg-brand-800 text-white rounded-full hover:bg-brand-900 transition-all shadow-md hover:shadow-lg active:scale-95 font-bold text-sm tracking-wide"
      >
        <Wand2 className="w-4 h-4" /> 
        Generate Image
      </button>
    </div>
  );
};

import React, { useMemo } from 'react';
import { ImageRenderer } from './ImageRenderer';
import { Download, BookOpen, Menu } from 'lucide-react';

interface EbookReaderProps {
  content: string;
  isGenerating: boolean;
}

// Helper to parse content into blocks (text vs image prompts)
const parseContent = (text: string) => {
  const lines = text.split('\n');
  const blocks: { type: 'text' | 'image' | 'title'; content: string; id: string }[] = [];

  let currentTextBlock = '';
  let titleFound = false;

  lines.forEach((line, index) => {
    // Check for Image Tag
    const imageMatch = line.match(/<<IMAGE_PROMPT:\s*(.*?)>>/);

    if (imageMatch) {
      // Push accumulated text
      if (currentTextBlock.trim()) {
        blocks.push({ type: 'text', content: currentTextBlock, id: `txt-${index}` });
        currentTextBlock = '';
      }
      // Push image block
      blocks.push({ type: 'image', content: imageMatch[1], id: `img-${index}` });
    } 
    // Check for Main Title (Simple heuristic: First generic text line or [EBOOK TITLE])
    else if (!titleFound && (line.includes('[EBOOK TITLE]') || (line.trim().length > 0 && index < 5 && !line.startsWith('Topic:')))) {
       // Push accumulated text
       if (currentTextBlock.trim()) {
        blocks.push({ type: 'text', content: currentTextBlock, id: `txt-${index}-prev` });
        currentTextBlock = '';
      }
      blocks.push({ type: 'title', content: line.replace('[EBOOK TITLE]', '').trim(), id: `title-${index}` });
      titleFound = true;
    }
    else {
      currentTextBlock += line + '\n';
    }
  });

  if (currentTextBlock.trim()) {
    blocks.push({ type: 'text', content: currentTextBlock, id: `txt-end` });
  }

  return blocks;
};

