  }

  return (
    <div className="h-full flex flex-col bg-brand-100/50 border-l border-brand-200">
      <div className="h-16 bg-white/80 backdrop-blur-md border-b border-brand-200 flex items-center justify-between px-6 sticky top-0 z-20 print-hide">
        <span className="font-serif font-bold text-brand-900 truncate max-w-[60%]">
          {topic || "Untitled Ebook"}
