      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth" id="reader-container">
        <div className="max-w-3xl mx-auto bg-white shadow-2xl min-h-[calc(100vh-10rem)] p-8 md:p-12 rounded-sm print:shadow-none print:p-0 print:w-full print:max-w-none">

          {blocks.map((block) => {
            if (block.type === 'title') {
              return (
                <h1 key={block.id} className="text-3xl md:text-5xl font-serif font-black text-brand-900 mb-6 tracking-tight leading-tight border-b-4 border-brand-200 pb-6 text-center print:text-black">
                  {block.content}
                </h1>
              );
            }

            if (block.type === 'image') {
              imageCount++;
              const isCover = imageCount === 1;
              return (
                <div key={block.id} className="break-inside-avoid page-break-inside-avoid">
                   <ImageRenderer prompt={block.content} isCover={isCover} />
                </div>
              );
            }

            return (
              <div key={block.id} className="prose prose-lg max-w-none prose-headings:font-serif prose-headings:text-brand-900 prose-p:text-gray-700 prose-p:leading-relaxed prose-li:text-gray-700 font-serif">
                  {block.content.split('\n').map((line, i) => {
                      if (line.startsWith('CHAPTER') || line.startsWith('## ')) {
                         const title = line.replace('## ', '').replace('**', '').replace('**', '');
                         return <h2 key={i} className="text-2xl font-bold mt-10 mb-5 text-brand-800 print-break">{title}</h2>; 
                      }
                      if (line.startsWith('### ')) {
                          return <h3 key={i} className="text-lg font-bold mt-6 mb-3 text-brand-700">{line.replace('### ', '')}</h3>;
                      }
                      if (line.trim().startsWith('- ')) {
                          return <li key={i} className="ml-4 list-disc pl-2 mb-2">{line.replace('- ', '')}</li>;
                      }
                      if (line.trim().length === 0) {
                          return <br key={i} />;
                      }
                      const parts = line.split(/(\*\*.*?\*\*)/);
                      return (
                          <p key={i} className="mb-4 text-base md:text-lg">
                              {parts.map((part, idx) => {
                                  if (part.startsWith('**') && part.endsWith('**')) {
                                      return <strong key={idx}>{part.slice(2, -2)}</strong>;
                                  }
                                  return part;
                              })}
                          </p>
                      );
                  })}
