import React, { useState, useEffect, useRef } from 'react';
import { streamEbookContent, createConsultantChat } from './services/gemini';
import { EbookReader } from './components/EbookReader';
import { ChatInterface } from './components/ChatInterface';
import { Chat } from "@google/genai";

interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

const App = () => {
  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isSending, setIsSending] = useState(false);

  // Ebook State
  const [ebookContent, setEbookContent] = useState('');
  const [isGeneratingEbook, setIsGeneratingEbook] = useState(false);
  const [currentTopic, setCurrentTopic] = useState('');

  // Gemini Chat Instance Ref
  const chatSessionRef = useRef<Chat | null>(null);

  // Initialize Chat Session on Mount
  useEffect(() => {
    if (!chatSessionRef.current) {
      chatSessionRef.current = createConsultantChat();
      // Optional: Add an initial greeting from the bot if desired, 
      // but let's let the UI empty state handle the prompt for the user.
    }
  }, []);

  const handleSendMessage = async (text: string) => {
    if (!chatSessionRef.current) return;

    // Optimistic Update
    setMessages(prev => [...prev, { role: 'user', text }]);
    setIsSending(true);

    try {
      // Send to Gemini
      const response = await chatSessionRef.current.sendMessage({ message: text });

      // Handle Function Calls (Trigger Ebook Generation)
      const functionCalls = response.functionCalls;
      if (functionCalls && functionCalls.length > 0) {
        const call = functionCalls[0];
        if (call.name === 'generate_ebook') {
          const args = call.args as any;
          const { topic, details } = args;

          setCurrentTopic(topic);
          setMessages(prev => [...prev, { 
            role: 'model', 
            text: `Perfect. I have everything I need. Starting the writing process for "${topic}" now...` 
          }]);

          setIsGeneratingEbook(true);
          setEbookContent(''); // Clear previous if any

          // Start Streaming Ebook
          await streamEbookContent(topic, details, (chunk) => {
            setEbookContent(prev => prev + chunk);
          });

          setIsGeneratingEbook(false);
          setMessages(prev => [...prev, { 
            role: 'model', 
            text: "Your ebook is complete! You can review it on the right and download it as a PDF." 
          }]);
        }
      } else {
        // Standard Text Response
        const responseText = response.text || "I didn't quite catch that.";
        setMessages(prev => [...prev, { role: 'model', text: responseText }]);
      }
    } catch (error) {
      console.error("Chat error:", error);
      setMessages(prev => [...prev, { role: 'model', text: "I encountered an error. Please try again." }]);
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="flex h-screen overflow-hidden bg-brand-50">
      {/* Left Panel: Chat Interface (35% width on desktop, full on mobile if not previewing) */}
      <div className={`w-full md:w-[35%] lg:w-[30%] h-full flex flex-col z-10 shadow-xl ${isGeneratingEbook || ebookContent ? 'hidden md:flex' : 'flex'}`}>
        <ChatInterface 
          messages={messages} 
          onSendMessage={handleSendMessage}
          isSending={isSending}
        />
      </div>

      {/* Right Panel: Ebook Preview (65% width) */}
      <div className={`w-full md:w-[65%] lg:w-[70%] h-full relative ${!isGeneratingEbook && !ebookContent ? 'hidden md:block' : 'block'}`}>
        <EbookReader 
          content={ebookContent} 
          isGenerating={isGeneratingEbook}
          topic={currentTopic}
        />

        {/* Mobile View Toggle (Visible only on mobile when content exists) */}
        <div className="md:hidden fixed bottom-4 right-4 z-50">
           {/* Mobile implementation logic could be added here if needed, sticking to split view desktop focus per prompt's "side by side" implication */}
        </div>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// The specific persona instructions from the user prompt for the Writer
const EBOOK_CREATOR_SYSTEM_INSTRUCTION = `
You are a Professional Ebook Creator AI. You create premium ebooks with visuals.

***CRITICAL WRITING STYLE RULES***
1. **LANGUAGE LEVEL**: You must write in extremely SIMPLE language. Use words that a 1st Grade student (6-year-old) can understand.
2. **NO AI JARGON**: Do not use complex words like "leverage", "utilize", "comprehensive", "landscape". Use simple words like "use", "full", "world".
3. **TONE**: Friendly, easy, and direct.

***STRUCTURE & FORMAT (Follow Exactly)***
[EBOOK TITLE]
Subtitle

<<IMAGE_PROMPT: Professional Cover art for the book>>

[AUTHOR PAGE]
About the Author
(Write a friendly, professional bio for an expert on this topic)
<<IMAGE_PROMPT: A friendly professional photo of the author>>

[INTRODUCTION]
(A warm welcome explaining what this book is about)

Table of Contents

CHAPTER 1 - Title
<<IMAGE_PROMPT: Visual for Chapter 1>>
(Content with Bullet points, simple steps, and easy examples)

CHAPTER 2 - Title
<<IMAGE_PROMPT: Visual for Chapter 2>>
(Content...)

(Continue for 5-7 Chapters)

Final Summary
Bonus Tools
✔ EBOOK COMPLETE.

***IMAGE RULES***
- Whenever you need an image, use this tag on its own line:
  <<IMAGE_PROMPT: Detailed description of the image>>
`;

const generateEbookTool: FunctionDeclaration = {
  name: "generate_ebook",
  description: "Triggers the generation of the ebook based on the collected details.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      topic: { type: Type.STRING, description: "The main topic/title of the ebook" },
      language: { 
        type: Type.STRING, 
        enum: ["English", "Hindi", "Hinglish"],
        description: "The language to write the ebook in." 
      },
      details: { type: Type.STRING, description: "Detailed summary of audience, tone, chapters, and specific content requirements" },
    },
    required: ["topic", "language", "details"],
  },
};

export const createConsultantChat = () => {
  return ai.chats.create({
    model: 'gemini-2.5-flash',
    config: {
      systemInstruction: "You are a friendly Ebook Publishing Assistant. \n\n1. Ask the user what topic they want to write about.\n2. Ask which language they prefer: English, Hindi, or Hinglish.\n3. Ask for any specific details (audience, goal).\n4. Once you have the TOPIC, LANGUAGE, and DETAILS, call the `generate_ebook` function immediately. Do not write the ebook yourself in the chat.",
      tools: [{ functionDeclarations: [generateEbookTool] }],
    }
  });
};

export const streamEbookContent = async (
  topic: string,
  details: string,
  language: string,
  onChunk: (text: string) => void
) => {
  try {
    const prompt = `
    Task: Write a complete ebook.
    Topic: ${topic}
    Language: ${language} (Write strictly in this language).
    Details: ${details}

    Remember: Use very simple, easy-to-read words (Grade 1 level). No heavy vocabulary.
    Start creating now following the structure.
    `;

    const response = await ai.models.generateContentStream({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: EBOOK_CREATOR_SYSTEM_INSTRUCTION,
        temperature: 0.7,
      }
    });

    for await (const chunk of response) {
      if (chunk.text) {
        onChunk(chunk.text);
      }
    }
  } catch (error) {
    console.error("Error generating ebook text:", error);
    throw error;
  }
};

export const generateEbookImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: "High quality, professional, book illustration style: " + prompt }]
      },
      config: {
         imageConfig: {
           aspectRatio: "16:9",
         }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data found in response");
  } catch (error) {
    console.error("Error generating image:", error);
    return `https://picsum.photos/seed/${encodeURIComponent(prompt)}/800/450`; 
  }
