import React, { useMemo, useRef, useState } from 'react';
import { ImageRenderer } from './ImageRenderer';
import { Download, BookOpen, Loader2, CheckCircle } from 'lucide-react';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

interface EbookReaderProps {
  content: string;
  isGenerating: boolean;
  topic?: string;
}

const parseContent = (text: string) => {
  const lines = text.split('\n');
  const blocks: { type: 'text' | 'image' | 'title' | 'author_header' | 'intro_header'; content: string; id: string }[] = [];

  let currentTextBlock = '';

  // Regex to identify headers
  const isImage = (line: string) => line.match(/<<IMAGE_PROMPT:\s*(.*?)>>/);
  const isMainTitle = (line: string) => line.includes('[EBOOK TITLE]');
  const isAuthorHeader = (line: string) => line.includes('[AUTHOR PAGE]');
  const isIntroHeader = (line: string) => line.includes('[INTRODUCTION]');

  lines.forEach((line, index) => {
    const imageMatch = isImage(line);

    if (imageMatch) {
      if (currentTextBlock.trim()) blocks.push({ type: 'text', content: currentTextBlock, id: `txt-${index}` });
      currentTextBlock = '';
      blocks.push({ type: 'image', content: imageMatch[1], id: `img-${index}` });
    } 
    else if (isMainTitle(line)) {
       if (currentTextBlock.trim()) blocks.push({ type: 'text', content: currentTextBlock, id: `txt-${index}` });
       currentTextBlock = '';
       blocks.push({ type: 'title', content: line.replace('[EBOOK TITLE]', '').trim(), id: `title-${index}` });
    }
    else if (isAuthorHeader(line)) {
       if (currentTextBlock.trim()) blocks.push({ type: 'text', content: currentTextBlock, id: `txt-${index}` });
       currentTextBlock = '';
       blocks.push({ type: 'author_header', content: "About the Author", id: `auth-${index}` });
    }
    else if (isIntroHeader(line)) {
       if (currentTextBlock.trim()) blocks.push({ type: 'text', content: currentTextBlock, id: `txt-${index}` });
       currentTextBlock = '';
       blocks.push({ type: 'intro_header', content: "Introduction", id: `intro-${index}` });
    }
    else {
      currentTextBlock += line + '\n';
    }
  });

  if (currentTextBlock.trim()) {
    blocks.push({ type: 'text', content: currentTextBlock, id: `txt-end` });
  }

  return blocks;
};

export const EbookReader: React.FC<EbookReaderProps> = ({ content, isGenerating, topic }) => {
  const blocks = useMemo(() => parseContent(content), [content]);
  const contentRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);

  const handleDownloadPDF = async () => {
    if (!contentRef.current) return;

    setIsDownloading(true);

    try {
      const element = contentRef.current;

      // Use html2canvas to capture the visual representation
      // Scale: 2 improves quality
      const canvas = await html2canvas(element, {
        scale: 2,
        useCORS: true,
        logging: false,
        backgroundColor: '#ffffff'
      });

      const imgData = canvas.toDataURL('image/jpeg', 1.0);

      // A4 dimensions in mm
      const pdfWidth = 210;
      const pdfHeight = 297;

      const imgWidth = pdfWidth;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      const pdf = new jsPDF('p', 'mm', 'a4');

      // If the content is taller than one page, we might need a simple approach for now
      // Since splitting images is complex, we will create a PDF with the exact height of the content
      // Or simply fit it to pages. For now, let's do a long PDF or page breaks.
      // Simple approach: One long page (custom size) to ensure nothing is cut off
      // OR Standard approach: Fit to A4

      // Let's go with a custom height PDF to ensure 100% fidelity without cutting text lines
      const customPdf = new jsPDF('p', 'mm', [pdfWidth, imgHeight]);
      customPdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, imgHeight);
      customPdf.save(`${topic || 'ebook'}.pdf`);

    } catch (error) {
      console.error("PDF Generation failed", error);
      alert("Could not generate PDF. Please try again.");
    } finally {
      setIsDownloading(false);
    }
  };

  let imageCount = 0;

  if (!content && !isGenerating) {
    return (
      <div className="h-full flex flex-col items-center justify-center bg-white text-slate-400 p-8 text-center border-l border-brand-200">
        <BookOpen className="w-20 h-20 mb-6 opacity-30 text-slate-900" />
        <h3 className="text-2xl font-serif font-bold mb-3 text-slate-800">Ebook Preview</h3>
        <p className="max-w-xs text-base text-slate-600">Your professional ebook will appear here. The AI will write the text and generate images automatically.</p>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-slate-50 border-l border-brand-200">
      <div className="h-16 bg-white border-b border-brand-200 flex items-center justify-between px-6 sticky top-0 z-20 shadow-sm print-hide">
        <span className="font-serif font-bold text-slate-900 truncate max-w-[50%] text-lg">
          {topic || "Untitled Ebook"}
        </span>
        <div className="flex items-center gap-3">
             {isGenerating && (
                <div className="flex items-center gap-2 text-brand-700 text-xs font-bold animate-pulse bg-brand-50 px-3 py-1.5 rounded-full border border-brand-200">
                    <Loader2 className="w-3 h-3 animate-spin" />
                    WRITING...
                </div>
            )}
            <button 
                onClick={handleDownloadPDF}
                disabled={content.length < 100 || isDownloading}
                className="flex items-center gap-2 px-4 py-2 bg-brand-800 text-white rounded-lg hover:bg-brand-900 disabled:opacity-50 disabled:cursor-not-allowed transition-all font-bold text-sm shadow-md"
                title="Download PDF"
            >
                {isDownloading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" /> Processing...
                  </>
                ) : (
                  <>
                    <Download className="w-4 h-4" /> Download PDF
                  </>
                )}
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth bg-slate-100/50">
        {/* The Content Area to be Captured */}
        <div ref={contentRef} className="max-w-[210mm] mx-auto bg-white shadow-xl min-h-[calc(100vh-10rem)] p-[20mm] rounded-sm text-slate-900">

          {blocks.map((block) => {
            if (block.type === 'title') {
              return (
                <div key={block.id} className="text-center mb-16 mt-10">
                   <h1 className="text-5xl md:text-6xl font-serif font-black text-slate-900 mb-6 tracking-tight leading-tight">
                    {block.content}
                  </h1>
                  <div className="w-24 h-1 bg-brand-500 mx-auto rounded-full"></div>
                </div>
              );
            }

            if (block.type === 'author_header') {
                return (
                    <div key={block.id} className="mt-12 mb-6 border-b-2 border-slate-100 pb-2">
                        <h2 className="text-3xl font-serif font-bold text-slate-800">About the Author</h2>
                    </div>
                );
            }

            if (block.type === 'intro_header') {
                return (
                    <div key={block.id} className="mt-12 mb-6 border-b-2 border-slate-100 pb-2">
                        <h2 className="text-3xl font-serif font-bold text-slate-800">Introduction</h2>
                    </div>
                );
            }

            if (block.type === 'image') {
              imageCount++;
              const isCover = imageCount === 1;
              return (
                <div key={block.id} className="my-8">
                   <ImageRenderer prompt={block.content} isCover={isCover} />
                </div>
              );
            }

            return (
              <div key={block.id} className="prose prose-lg max-w-none font-serif text-slate-900">
                  {block.content.split('\n').map((line, i) => {
                      // Chapter Title
                      if (line.startsWith('CHAPTER') || line.startsWith('## ')) {
                         const title = line.replace('## ', '').replace('**', '').replace('**', '');
                         return <h2 key={i} className="text-3xl font-bold mt-16 mb-8 text-brand-900 border-l-4 border-brand-500 pl-4">{title}</h2>; 
                      }
                      // Subheading
                      if (line.startsWith('### ')) {
                          return <h3 key={i} className="text-xl font-bold mt-8 mb-4 text-slate-800">{line.replace('### ', '')}</h3>;
                      }
                      // List Items
                      if (line.trim().startsWith('- ')) {
                          return <li key={i} className="ml-6 list-disc pl-2 mb-3 text-slate-800">{line.replace('- ', '')}</li>;
                      }
                      // Empty Line
                      if (line.trim().length === 0) {
                          return <div key={i} className="h-4"></div>;
                      }
                      // Paragraphs
                      const parts = line.split(/(\*\*.*?\*\*)/);
                      return (
                          <p key={i} className="mb-4 text-lg leading-relaxed text-slate-900">
                              {parts.map((part, idx) => {
                                  if (part.startsWith('**') && part.endsWith('**')) {
                                      return <strong key={idx} className="font-bold text-black">{part.slice(2, -2)}</strong>;
                                  }
                                  return part;
                              })}
                          </p>
                      );
                  })}
              </div>
            );
          })}

           {!isGenerating && content.length > 0 && (
                 <div className="mt-32 pt-12 border-t border-slate-100 text-center">
                    <div className="inline-flex items-center gap-2 text-brand-600 font-bold uppercase tracking-widest text-xs">
                        <CheckCircle className="w-4 h-4" />
                        <span>Professionally Generated by ProBook AI</span>
                    </div>
                 </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { streamEbookContent, createConsultantChat } from './services/gemini';
import { EbookReader } from './components/EbookReader';
import { ChatInterface } from './components/ChatInterface';
import { Chat } from "@google/genai";

interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

const App = () => {
  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isSending, setIsSending] = useState(false);

  // Ebook State
  const [ebookContent, setEbookContent] = useState('');
  const [isGeneratingEbook, setIsGeneratingEbook] = useState(false);
  const [currentTopic, setCurrentTopic] = useState('');

  // Gemini Chat Instance Ref
  const chatSessionRef = useRef<Chat | null>(null);

  // Initialize Chat Session on Mount
  useEffect(() => {
    if (!chatSessionRef.current) {
      chatSessionRef.current = createConsultantChat();
    }
  }, []);

  const handleSendMessage = async (text: string) => {
    if (!chatSessionRef.current) return;

    // Optimistic Update
    setMessages(prev => [...prev, { role: 'user', text }]);
    setIsSending(true);

    try {
      // Send to Gemini
      const response = await chatSessionRef.current.sendMessage({ message: text });

      // Handle Function Calls (Trigger Ebook Generation)
      const functionCalls = response.functionCalls;
      if (functionCalls && functionCalls.length > 0) {
        const call = functionCalls[0];
        if (call.name === 'generate_ebook') {
          const args = call.args as any;
          const { topic, details, language } = args;

          const selectedLang = language || "English";

          setCurrentTopic(topic);
          setMessages(prev => [...prev, { 
            role: 'model', 
            text: `Starting your ${selectedLang} ebook on "${topic}" with a dedicated Author Page...` 
          }]);

          setIsGeneratingEbook(true);
          setEbookContent(''); // Clear previous if any

          // Start Streaming Ebook
          await streamEbookContent(topic, details, selectedLang, (chunk) => {
            setEbookContent(prev => prev + chunk);
          });

          setIsGeneratingEbook(false);
          setMessages(prev => [...prev, { 
            role: 'model', 
            text: "Done! You can now download the complete PDF with visuals." 
          }]);
        }
      } else {
        // Standard Text Response
        const responseText = response.text || "I didn't quite catch that.";
        setMessages(prev => [...prev, { role: 'model', text: responseText }]);
      }
    } catch (error) {
      console.error("Chat error:", error);
      setMessages(prev => [...prev, { role: 'model', text: "I encountered an error. Please try again." }]);
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="flex h-screen overflow-hidden bg-brand-50">
      {/* Left Panel: Chat Interface (35% width on desktop, full on mobile if not previewing) */}
      <div className={`w-full md:w-[35%] lg:w-[30%] h-full flex flex-col z-10 shadow-xl ${isGeneratingEbook || ebookContent ? 'hidden md:flex' : 'flex'}`}>
        <ChatInterface 
          messages={messages} 
          onSendMessage={handleSendMessage}
          isSending={isSending}
        />
      </div>

      {/* Right Panel: Ebook Preview (65% width) */}
      <div className={`w-full md:w-[65%] lg:w-[70%] h-full relative ${!isGeneratingEbook && !ebookContent ? 'hidden md:block' : 'block'}`}>
        <EbookReader 
          content={ebookContent} 
          isGenerating={isGeneratingEbook}
          topic={currentTopic}
        />
      </div>
    </div>
  );
};

export default App;

