      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data found in response");
    } catch (error: any) {
      // Check for Rate Limit errors (429) or other API issues
      const isRateLimit = error?.status === 429 || error?.error?.code === 429 || (error?.message && error.message.includes('429'));

      if (isRateLimit) {
         console.warn("Quota exceeded (429) for image generation. Using fallback placeholder.");
      } else {
         console.error("Error generating image:", error);
      }

      // Fallback to a placeholder service if generation fails
      return `https://picsum.photos/seed/${encodeURIComponent(prompt.substring(0, 50))}/800/450`; 
    }
  });
};

import React, { useMemo, useRef, useState } from 'react';
import { ImageRenderer } from './ImageRenderer';
import { Download, BookOpen, Loader2, CheckCircle } from 'lucide-react';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

interface EbookReaderProps {
  content: string;
  isGenerating: boolean;
  topic?: string;
}

// Helper to determine block type
const getBlockType = (line: string, index: number): string => {
  if (line.match(/<<IMAGE_PROMPT:\s*(.*?)>>/)) return 'image';
  if (line.includes('[EBOOK TITLE]')) return 'title';
  if (line.includes('[AUTHOR PAGE]')) return 'author_header';
  if (line.includes('[INTRODUCTION]')) return 'intro_header';
  if (line.startsWith('CHAPTER') || line.startsWith('## ')) return 'chapter_header';
  return 'text';
};

// Parse content into logical sections for Page Breaking
const parseContentToSections = (text: string) => {
  const lines = text.split('\n');
  const sections: { type: string; blocks: any[] }[] = [];
  let currentBlocks: any[] = [];
  let currentSectionType = 'front_matter';

  const startNewSection = (type: string) => {
    if (currentBlocks.length > 0) {
      sections.push({ type: currentSectionType, blocks: [...currentBlocks] });
    }
    currentBlocks = [];
    currentSectionType = type;
  };

  let currentTextBlock = '';

  const flushText = (idSuffix: string) => {
    if (currentTextBlock.trim()) {
      currentBlocks.push({ type: 'text', content: currentTextBlock, id: `txt-${idSuffix}` });
      currentTextBlock = '';
    }
  };

  lines.forEach((line, index) => {
    const type = getBlockType(line, index);

    // If it's a major header, we usually start a new page section
    if (type === 'title') {
      flushText(`${index}-prev`);
      startNewSection('title_page');
      currentBlocks.push({ type: 'title', content: line.replace('[EBOOK TITLE]', '').trim(), id: `title-${index}` });
    } else if (type === 'author_header') {
      flushText(`${index}-prev`);
      startNewSection('author_page');
      currentBlocks.push({ type: 'header_main', content: "About the Author", id: `auth-${index}` });
    } else if (type === 'intro_header') {
      flushText(`${index}-prev`);
      startNewSection('intro_page');
      currentBlocks.push({ type: 'header_main', content: "Introduction", id: `intro-${index}` });
    } else if (type === 'chapter_header') {
      flushText(`${index}-prev`);
      startNewSection('chapter_page');
      const title = line.replace('## ', '').replace(/\*\*/g, '').trim(); // Remove ** artifacts from title
      currentBlocks.push({ type: 'header_chapter', content: title, id: `chap-${index}` });
    } else if (type === 'image') {
      flushText(`${index}-prev`);
      const match = line.match(/<<IMAGE_PROMPT:\s*(.*?)>>/);
      if (match) {
        currentBlocks.push({ type: 'image', content: match[1], id: `img-${index}` });
      }
    } else {
      // Accumulate text
      currentTextBlock += line + '\n';
    }
  });

  flushText('end');

  if (currentBlocks.length > 0) {
    sections.push({ type: currentSectionType, blocks: [...currentBlocks] });
  }

  return sections;
};

export const EbookReader: React.FC<EbookReaderProps> = ({ content, isGenerating, topic }) => {
  const sections = useMemo(() => parseContentToSections(content), [content]);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);

  // Render text without Markdown artifacts (removes **)
  const renderText = (text: string) => {
    const lines = text.split('\n');
    return lines.map((line, i) => {
      if (line.trim().length === 0) return <div key={i} className="h-4" />;

      // Handle subtitles (lines starting with Subtitle)
      if (line.trim().startsWith('Subtitle')) {
        return <p key={i} className="text-xl text-slate-500 italic text-center mb-8">{line.replace('Subtitle', '').trim()}</p>;
      }

      // Handle Lists
      if (line.trim().startsWith('- ')) {
        return <li key={i} className="ml-6 list-disc pl-2 mb-2 text-slate-800 text-base">{renderLineWithBold(line.replace('- ', ''))}</li>;
      }

      // Handle Subheadings (###)
      if (line.startsWith('### ')) {
        return <h3 key={i} className="text-xl font-bold mt-6 mb-3 text-slate-800">{line.replace('### ', '')}</h3>;
      }

      // Normal Paragraph
      return <p key={i} className="mb-4 text-lg leading-relaxed text-slate-900">{renderLineWithBold(line)}</p>;
    });
  };

  // Helper to process **bold** text without leaving stars
  const renderLineWithBold = (line: string) => {
    const parts = line.split(/(\*\*.*?\*\*)/);
    return parts.map((part, idx) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={idx} className="font-bold text-black">{part.slice(2, -2)}</strong>;
      }
      return part;
    });
  };

  const handleDownloadPDF = async () => {
    if (!containerRef.current) return;
    setIsDownloading(true);

    try {
      const pdf = new jsPDF('p', 'mm', 'a4');
      const pdfWidth = 210;
      const pdfHeight = 297;

      // Select all section containers
      const sectionElements = containerRef.current.querySelectorAll('.pdf-section');

      for (let i = 0; i < sectionElements.length; i++) {
        const element = sectionElements[i] as HTMLElement;

        // Capture section
        const canvas = await html2canvas(element, {
          scale: 2, // High resolution
          useCORS: true,
          logging: false,
          backgroundColor: '#ffffff'
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.95);
        const imgWidth = pdfWidth;
        const imgHeight = (canvas.height * imgWidth) / canvas.width;

        // If it's not the first page, add a new page
        if (i > 0) pdf.addPage();

        // If image height exceeds A4 (very long chapter), we might squish or crop.
        // For this simple implementation, we'll try to fit it or let it run (users requested "full ebook").
        // To strictly handle multi-page chapters within a section would require complex splitting.
        // Current compromise: We render the section as is. If it's huge, PDF might look long.
        // BUT, since we split by Sections now, most sections (Intro, Author) fit on one page.
        // Long chapters might need multiple pages, but html2canvas captures the whole div.
        // If height > 297, we need to split the image.

        let heightLeft = imgHeight;
        let position = 0;

        // First page of the section
        pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight);
        heightLeft -= pdfHeight;

        // If section is longer than one A4 page, add extra pages
        while (heightLeft > 0) {
          position = position - pdfHeight; // Move the image up
          pdf.addPage();
          pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight);
          heightLeft -= pdfHeight;
        }
      }

      pdf.save(`${topic || 'ebook'}.pdf`);

    } catch (error) {
      console.error("PDF Generation failed", error);
      alert("Could not generate PDF. Please try again.");
    } finally {
      setIsDownloading(false);
    }
  };

  let imageCount = 0;

  if (!content && !isGenerating) {
    return (
      <div className="h-full flex flex-col items-center justify-center bg-white text-slate-400 p-8 text-center border-l border-brand-200">
        <BookOpen className="w-20 h-20 mb-6 opacity-30 text-slate-900" />
        <h3 className="text-2xl font-serif font-bold mb-3 text-slate-800">Ebook Preview</h3>
        <p className="max-w-xs text-base text-slate-600">Your professional ebook will appear here.</p>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-slate-50 border-l border-brand-200">
      <div className="h-16 bg-white border-b border-brand-200 flex items-center justify-between px-6 sticky top-0 z-20 shadow-sm print-hide">
        <span className="font-serif font-bold text-slate-900 truncate max-w-[50%] text-lg">
          {topic || "Untitled Ebook"}
        </span>
        <div className="flex items-center gap-3">
             {isGenerating && (
                <div className="flex items-center gap-2 text-brand-700 text-xs font-bold animate-pulse bg-brand-50 px-3 py-1.5 rounded-full border border-brand-200">
                    <Loader2 className="w-3 h-3 animate-spin" />
                    WRITING...
                </div>
            )}
            <button 
                onClick={handleDownloadPDF}
                disabled={content.length < 100 || isDownloading}
                className="flex items-center gap-2 px-4 py-2 bg-brand-800 text-white rounded-lg hover:bg-brand-900 disabled:opacity-50 disabled:cursor-not-allowed transition-all font-bold text-sm shadow-md"
                title="Download PDF"
            >
                {isDownloading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" /> Creating PDF...
                  </>
                ) : (
                  <>
                    <Download className="w-4 h-4" /> Download PDF
                  </>
                )}
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth bg-slate-100/50">
        <div ref={containerRef} className="max-w-[210mm] mx-auto">
          {/* Loop through sections to render distinct pages */}
          {sections.map((section, secIdx) => (
            <div 
              key={secIdx} 
              className={`pdf-section bg-white shadow-sm p-[20mm] rounded-sm text-slate-900 mb-8 min-h-[297mm] flex flex-col ${secIdx === 0 ? 'justify-center' : ''}`}
            >
              {section.blocks.map((block) => {
                if (block.type === 'title') {
                  return (
                    <div key={block.id} className="text-center mb-10">
                       <h1 className="text-5xl md:text-6xl font-serif font-black text-slate-900 mb-6 tracking-tight leading-tight uppercase">
                        {block.content}
                      </h1>
                      <div className="w-24 h-2 bg-brand-600 mx-auto"></div>
                    </div>
                  );
                }

                if (block.type === 'header_main') {
                    return (
                        <div key={block.id} className="mb-8 border-b-4 border-slate-100 pb-4">
                            <h2 className="text-4xl font-serif font-bold text-slate-900">{block.content}</h2>
                        </div>
                    );
                }

                if (block.type === 'header_chapter') {
                    return (
                        <div key={block.id} className="mb-8 pt-4">
                            <span className="text-brand-600 font-bold tracking-widest text-sm uppercase block mb-2">Chapter</span>
                            <h2 className="text-4xl font-serif font-bold text-slate-900 leading-tight">{block.content}</h2>
                        </div>
                    );
                }

                if (block.type === 'image') {
                  imageCount++;
                  const isCover = imageCount === 1;
                  return (
                    <div key={block.id} className="my-6">
                       <ImageRenderer prompt={block.content} isCover={isCover} />
                    </div>
                  );
                }

                if (block.type === 'text') {
                  // If it's Table of Contents, render differently (smaller text)
                  if (section.blocks.some(b => b.content && b.content.includes && b.content.includes('Table of Contents'))) {
                     return (
                      <div key={block.id} className="prose prose-slate font-serif text-slate-700">
                          {renderText(block.content)}
                      </div>
                     )
                  }

                  return (
                    <div key={block.id} className="prose prose-lg max-w-none font-serif text-slate-900">
                        {renderText(block.content)}
                    </div>
                  );
                }
                return null;
              })}

              {/* Footer for non-cover pages */}
              {section.type !== 'title_page' && (
                 <div className="mt-auto pt-8 border-t border-slate-100 text-center text-slate-300 text-xs">
                    Page {secIdx + 1}
                 </div>
              )}
            </div>
          ))}

          {!isGenerating && content.length > 0 && (
                 <div className="py-12 text-center">
                    <div className="inline-flex items-center gap-2 text-brand-600 font-bold uppercase tracking-widest text-xs bg-brand-50 px-4 py-2 rounded-full">
                        <CheckCircle className="w-4 h-4" />
                        <span>Ebook Complete</span>
                    </div>
                 </div>
            )}
        </div>
      </div>
    </div>
  );
};

