  const flushText = (idSuffix: string) => {
    if (currentTextBlock.trim()) {
      currentBlocks.push({ type: 'text', content: currentTextBlock, id: `txt-${idSuffix}` });
      currentTextBlock = '';
    }
  };

  lines.forEach((line, index) => {
    const type = getBlockType(line);

    // Major Headers trigger a new section (New Page in PDF)
    if (type === 'title') {
      flushText(`${index}-prev`);
      startNewSection('title_page');
      currentBlocks.push({ type: 'title', content: line.replace('[EBOOK TITLE]', '').trim(), id: `title-${index}` });
    } else if (type === 'author_header') {
      flushText(`${index}-prev`);
      startNewSection('author_page');
      currentBlocks.push({ type: 'header_main', content: "About the Author", id: `auth-${index}` });
    } else if (type === 'intro_header') {
      flushText(`${index}-prev`);
      startNewSection('intro_page');
      currentBlocks.push({ type: 'header_main', content: "Introduction", id: `intro-${index}` });
    } else if (type === 'chapter_header') {
      flushText(`${index}-prev`);
      startNewSection('chapter_page');
      // Strip formatting artifacts from titles
      const title = line.replace('## ', '').replace(/\*\*/g, '').trim(); 
      currentBlocks.push({ type: 'header_chapter', content: title, id: `chap-${index}` });
    } else if (type === 'image') {
      flushText(`${index}-prev`);
      const match = line.match(/<<IMAGE_PROMPT:\s*(.*?)>>/);
      if (match) {
        currentBlocks.push({ type: 'image', content: match[1], id: `img-${index}` });
      }
    } else {
      // Accumulate text lines into a block
      currentTextBlock += line + '\n';
    }
  });

  flushText('end');

  if (currentBlocks.length > 0) {
    sections.push({ type: currentSectionType, blocks: [...currentBlocks] });
  }

  return sections;
};

export const EbookReader: React.FC<EbookReaderProps> = ({ content, isGenerating, topic }) => {
  const sections = useMemo(() => parseContentToSections(content), [content]);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);

  // Render text without Markdown artifacts (removes **) and handles basic styling
  const renderText = (text: string, isTableOfContents: boolean = false) => {
    const lines = text.split('\n');
    return lines.map((line, i) => {
      if (line.trim().length === 0) return <div key={i} className="h-4" />;

      // Handle subtitles (lines starting with Subtitle)
      if (line.trim().startsWith('Subtitle')) {
        return <p key={i} className="text-xl text-slate-500 italic text-center mb-8">{line.replace('Subtitle', '').trim()}</p>;
      }

      // Handle Lists
      if (line.trim().startsWith('- ')) {
        const content = line.replace('- ', '');
        return <li key={i} className={`ml-6 list-disc pl-2 mb-2 text-slate-800 ${isTableOfContents ? 'text-sm mb-1' : 'text-base'}`}>{renderLineWithBold(content)}</li>;
      }

      // Handle Subheadings (###)
      if (line.startsWith('### ')) {
        return <h3 key={i} className="text-xl font-bold mt-6 mb-3 text-slate-800">{line.replace('### ', '')}</h3>;
      }

      // Normal Paragraph
      return <p key={i} className={`mb-4 leading-relaxed text-slate-900 ${isTableOfContents ? 'text-sm' : 'text-lg'}`}>{renderLineWithBold(line)}</p>;
    });
  };

  // Helper to process **bold** text cleanly
  const renderLineWithBold = (line: string) => {
    const parts = line.split(/(\*\*.*?\*\*)/);
    return parts.map((part, idx) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={idx} className="font-bold text-black">{part.slice(2, -2)}</strong>;
      }
      return part;
    });
  };

  const handleDownloadPDF = async () => {
    if (!containerRef.current) return;
    setIsDownloading(true);

    try {
      const pdf = new jsPDF('p', 'mm', 'a4');
      const pdfWidth = 210; // A4 Width
      const pdfHeight = 297; // A4 Height

      // Select all section containers
      const sectionElements = containerRef.current.querySelectorAll('.pdf-section');

      let pageAdded = false;

      for (let i = 0; i < sectionElements.length; i++) {
        const element = sectionElements[i] as HTMLElement;

        // Capture section at high quality
        const canvas = await html2canvas(element, {
          scale: 2, 
          useCORS: true,
          logging: false,
          backgroundColor: '#ffffff'
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.95);
        const imgWidth = pdfWidth;
        const imgHeight = (canvas.height * imgWidth) / canvas.width;

        // If it's not the first section, we add a new page to start.
        if (i > 0 || pageAdded) {
           pdf.addPage();
           pageAdded = true;
        }

        // --- SPLIT LOGIC FOR LONG CHAPTERS ---
        // If content height > page height, we need to split the image across multiple PDF pages
        let heightLeft = imgHeight;
        let position = 0;

        // Add first page of the section
        pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight);
        heightLeft -= pdfHeight;

        // While there is still content left in this image (chapter) that hasn't been shown
        while (heightLeft > 0) {
          position = position - pdfHeight; // Move the image UP (negative Y) to reveal the next part
          pdf.addPage();
          pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight);
          heightLeft -= pdfHeight;
        }
      }

      pdf.save(`${topic || 'ebook'}.pdf`);

    } catch (error) {
      console.error("PDF Generation failed", error);
      alert("Could not generate PDF. Please try again.");
    } finally {
      setIsDownloading(false);
    }
  };

  let imageCount = 0;

  if (!content && !isGenerating) {
    return (
      <div className="h-full flex flex-col items-center justify-center bg-white text-slate-400 p-8 text-center border-l border-brand-200">
