    },
    required: ["instruction"],
  },
};

export const createConsultantChat = () => {
  return ai.chats.create({
    model: 'gemini-2.5-flash',
    config: {
      systemInstruction: "You are a friendly Ebook Publishing Assistant. \n\n1. Ask the user what topic they want to write about.\n2. Ask which language they prefer: English, Hindi, or Hinglish.\n3. Ask for any specific details (audience, goal).\n4. Once you have the TOPIC, LANGUAGE, and DETAILS, call the `generate_ebook` function immediately. \n5. If the user wants to change/edit the ebook AFTER generation, call the `edit_ebook` function.",
      tools: [{ functionDeclarations: [generateEbookTool, editEbookTool] }],
    }
  });
};

export const streamEbookContent = async (
  topic: string,
  details: string,
  language: string,
  onChunk: (text: string) => void,
  currentContent?: string
) => {
  try {
    let prompt = ``;

    if (currentContent) {
      // Editing Mode
      prompt = `
      Task: Edit the following ebook content.
      Instruction: ${details}
      Topic: ${topic}
      Language: ${language}

      Current Content:
      ${currentContent}

      Output the FULLY rewritten ebook from start to finish with the changes applied. Maintain the structure tags ([EBOOK TITLE], etc).
      `;
    } else {
      // Creation Mode
      prompt = `
      Task: Write a complete, premium ebook.
      Topic: ${topic}
      Language: ${language} (Write strictly in this language).
      Details: ${details}

      Structure Requirements:
      1. **Page 1**: Title, Subtitle, Cover Image ONLY.
      2. **Page 2**: Table of Contents ONLY (List style, MUST fit on one page).
      3. **Page 3**: Author Page ONLY.
      4. **Page 4**: Introduction ONLY.
      5. **Page 5+**: Chapters (Start each chapter on a new page).

      Ensure no "blank" content pages. Fill them with text.
      Start creating now.
      `;
    }

    const response = await ai.models.generateContentStream({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: EBOOK_CREATOR_SYSTEM_INSTRUCTION,
        temperature: 0.7,
        tools: [{ googleSearch: {} }] // Added Google Search Grounding
      }
    });

    for await (const chunk of response) {
      if (chunk.text) {
        onChunk(chunk.text);
      }
    }
  } catch (error) {
    console.error("Error generating ebook text:", error);
    throw error;
  }
};

// Queue system to prevent Rate Limit (429) errors during image generation bursts
class RequestQueue {
  private queue: (() => Promise<void>)[] = [];
  private isProcessing = false;
  // 4 seconds delay between image requests to stay safe within free tier limits
  private delayMs = 4000; 

  enqueue<T>(task: () => Promise<T>): Promise<T> {
    return new Promise((resolve, reject) => {
      this.queue.push(async () => {
        try {
          const result = await task();
          resolve(result);
        } catch (err) {
          reject(err);
        }
      });
      this.process();
    });
  }

  private async process() {
    if (this.isProcessing) return;
    this.isProcessing = true;

    while (this.queue.length > 0) {
      const task = this.queue.shift();
      if (task) {
        await task();
        if (this.queue.length > 0) {
          // Wait before processing the next item
          await new Promise(resolve => setTimeout(resolve, this.delayMs));
        }
      }
    }
    this.isProcessing = false;
  }
}

const imageQueue = new RequestQueue();

export const generateEbookImage = async (prompt: string): Promise<string> => {
  // Enqueue the request
  return imageQueue.enqueue(async () => {
    try {
      // Using gemini-2.5-flash-image to fix 403 Permission errors
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [{ text: "High quality, professional, book illustration style: " + prompt }]
        },
        config: {
           // tools not supported for flash-image
           // imageSize not supported for flash-image
        }
      });

      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }

      console.warn("Gemini returned no image data for prompt:", prompt);
      return `https://picsum.photos/seed/${encodeURIComponent(prompt.substring(0, 50))}/800/450`;

    } catch (error: any) {
      console.error("Image generation failed:", error);
      // Fallback
      return `https://picsum.photos/seed/${encodeURIComponent(prompt.substring(0, 50))}/800/450`; 
    }
  });
};

import React, { useMemo, useRef, useState } from 'react';
import { ImageRenderer } from './ImageRenderer';
import { Download, BookOpen, Loader2, CheckCircle } from 'lucide-react';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

interface EbookReaderProps {
  content: string;
  isGenerating: boolean;
  topic?: string;
}

// Helper to determine block type based on content markers
const getBlockType = (line: string): string => {
  if (line.match(/<<IMAGE_PROMPT:\s*(.*?)>>/)) return 'image';
  if (line.includes('[EBOOK TITLE]')) return 'title';
  if (line.includes('[TABLE OF CONTENTS]')) return 'toc_header';
  if (line.includes('[AUTHOR PAGE]')) return 'author_header';
  if (line.includes('[INTRODUCTION]')) return 'intro_header';
  if (line.includes('[CONCLUSION]')) return 'conclusion_header';
  if (line.startsWith('CHAPTER') || line.startsWith('## ')) return 'chapter_header';
  return 'text';
};

// Parse content into logical sections for Page Breaking and PDF generation
const parseContentToSections = (text: string) => {
  const lines = text.split('\n');
  const sections: { type: string; blocks: any[] }[] = [];
  let currentBlocks: any[] = [];
  let currentSectionType = 'front_matter';

  const startNewSection = (type: string) => {
    // Only push if there is content
    if (currentBlocks.length > 0) {
      sections.push({ type: currentSectionType, blocks: [...currentBlocks] });
    }
    currentBlocks = [];
    currentSectionType = type;
  };

  let currentTextBlock = '';

  const flushText = (idSuffix: string) => {
    if (currentTextBlock.trim()) {
      currentBlocks.push({ type: 'text', content: currentTextBlock, id: `txt-${idSuffix}` });
      currentTextBlock = '';
    }
  };

  lines.forEach((line, index) => {
    const type = getBlockType(line);

    // Major Headers trigger a new section (New Page in PDF)
    if (type === 'title') {
      flushText(`${index}-prev`);
      startNewSection('title_page');
      currentBlocks.push({ type: 'title', content: line.replace('[EBOOK TITLE]', '').trim(), id: `title-${index}` });
    } else if (type === 'toc_header') {
      flushText(`${index}-prev`);
      startNewSection('toc_page');
      currentBlocks.push({ type: 'header_main', content: "Table of Contents", id: `toc-${index}` });
    } else if (type === 'author_header') {
      flushText(`${index}-prev`);
      startNewSection('author_page');
      currentBlocks.push({ type: 'header_main', content: "About the Author", id: `auth-${index}` });
    } else if (type === 'intro_header') {
      flushText(`${index}-prev`);
      startNewSection('intro_page');
      currentBlocks.push({ type: 'header_main', content: "Introduction", id: `intro-${index}` });
    } else if (type === 'conclusion_header') {
      flushText(`${index}-prev`);
      startNewSection('conclusion_page');
      currentBlocks.push({ type: 'header_main', content: "Conclusion", id: `conc-${index}` });
    } else if (type === 'chapter_header') {
      flushText(`${index}-prev`);
      startNewSection('chapter_page');
      // Strip formatting artifacts from titles
      const title = line.replace('## ', '').replace(/\*\*/g, '').trim(); 
      currentBlocks.push({ type: 'header_chapter', content: title, id: `chap-${index}` });
    } else if (type === 'image') {
      flushText(`${index}-prev`);
      const match = line.match(/<<IMAGE_PROMPT:\s*(.*?)>>/);
      if (match) {
        currentBlocks.push({ type: 'image', content: match[1], id: `img-${index}` });
      }
    } else {
      // Accumulate text lines into a block
      currentTextBlock += line + '\n';
    }
  });

  flushText('end');

  if (currentBlocks.length > 0) {
    sections.push({ type: currentSectionType, blocks: [...currentBlocks] });
  }

  return sections;
};

export const EbookReader: React.FC<EbookReaderProps> = ({ content, isGenerating, topic }) => {
  const sections = useMemo(() => parseContentToSections(content), [content]);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);

  // Helper to process **bold** text cleanly
  const renderLineWithBold = (line: string) => {
    if (!line.includes('**')) return line;
    const parts = line.split(/(\*\*.*?\*\*)/g);
    return parts.map((part, idx) => {
      if (part.startsWith('**') && part.endsWith('**') && part.length >= 4) {
        return <strong key={idx} className="font-bold text-slate-900">{part.slice(2, -2)}</strong>;
      }
      return part;
    });
  };

  const renderText = (text: string, isTableOfContents: boolean = false) => {
    const lines = text.split('\n');
    return lines.map((line, i) => {
      if (line.trim().length === 0) return <div key={i} className="h-4" />;

      if (line.trim().startsWith('Subtitle')) {
        return <p key={i} className="text-xl md:text-2xl text-slate-500 italic text-center mb-8">{line.replace('Subtitle', '').trim()}</p>;
      }

      if (line.trim().startsWith('- ')) {
        const content = line.replace('- ', '');

        if (isTableOfContents) {
           return (
              <div key={i} className="flex items-baseline w-full py-2">
                  <span className="text-lg font-serif text-slate-900 font-medium whitespace-nowrap overflow-hidden text-ellipsis max-w-[85%]">
                      {renderLineWithBold(content)}
                  </span>
                  <span className="flex-1 mx-2 border-b-2 border-dotted border-slate-300 relative -top-1"></span>
                  {/* Visual placeholder for section separation, looks cleaner than empty space */}
              </div>
           );
        }

        const listClasses = 'ml-6 list-disc pl-2 mb-2 text-base';
        return <li key={i} className={`${listClasses} text-slate-800`}>{renderLineWithBold(content)}</li>;
      }

      if (line.startsWith('### ')) {
        return <h3 key={i} className="text-xl font-bold mt-6 mb-3 text-slate-800">{renderLineWithBold(line.replace('### ', ''))}</h3>;
      }

      return <p key={i} className={`mb-4 leading-relaxed text-slate-900 ${isTableOfContents ? 'text-lg' : 'text-lg'}`}>{renderLineWithBold(line)}</p>;
    });
  };

  const handleDownloadPDF = async () => {
    if (!containerRef.current) return;
    setIsDownloading(true);

    try {
      const pdf = new jsPDF('p', 'mm', 'a4');
      const pdfWidth = 210; 

      // Create Staging Area
      const staging = document.createElement('div');
      staging.className = 'pdf-staging bg-white text-slate-900 p-[20mm] flex flex-col font-serif'; 
      staging.style.width = '210mm';
      staging.style.minHeight = '297mm'; // Force A4 min-height
      staging.style.position = 'absolute';
      staging.style.left = '-9999px';
      staging.style.top = '0';
      document.body.appendChild(staging);

      const sections = Array.from(containerRef.current.querySelectorAll('.pdf-section'));

      for (let i = 0; i < sections.length; i++) {
        const section = sections[i] as HTMLElement;
        const isCover = section.dataset.type === 'title_page';

        // Single Page Logic for Front Matter
        if (isCover || section.dataset.type === 'toc_page' || section.dataset.type === 'author_page' || section.dataset.type === 'intro_page') {
             if (i > 0) pdf.addPage();

             // Clone the WHOLE section to staging to capture it exactly as one page
             staging.innerHTML = '';
             staging.appendChild(section.cloneNode(true));

             // We capture just the rendered content of the section
             const canvas = await html2canvas(staging.children[0] as HTMLElement, { scale: 2, useCORS: true });
             const imgData = canvas.toDataURL('image/jpeg', 0.95);

             // Calculated height to maintain aspect ratio, avoiding stretch
             const imgHeight = (canvas.height * pdfWidth) / canvas.width;
             pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, imgHeight);
             continue;
        }

        // --- Multi-Page Logic for Chapters ---
        staging.innerHTML = ''; 
        if (i > 0) pdf.addPage();

        const children = Array.from(section.children);

        const capturePage = async () => {
            const canvas = await html2canvas(staging, { scale: 2, useCORS: true });
            const imgData = canvas.toDataURL('image/jpeg', 0.95);
            pdf.addImage(imgData, 'JPEG', 0, 0, 210, 297); 
            staging.innerHTML = ''; 
        }

        for (let j = 0; j < children.length; j++) {
            const child = children[j].cloneNode(true) as HTMLElement;
            staging.appendChild(child);

            // Safety limit 1080px (approx 285mm) to leave footer space and avoid edge cuts
            if (staging.scrollHeight > 1080) { 
                staging.removeChild(child);

                // Force push if a single element is massive (rare)
                if (staging.children.length === 0) {
                     staging.appendChild(child); 
                     await capturePage();
                     pdf.addPage();
                } else {
                     await capturePage();
                     pdf.addPage();
                     staging.appendChild(child);
                }
            }
        }

        if (staging.children.length > 0) {
             await capturePage();
        }
      }

      document.body.removeChild(staging);
      pdf.save(`${topic || 'ebook'}.pdf`);

    } catch (error) {
      console.error("PDF Generation failed", error);
      alert("Could not generate PDF. Please try again.");
    } finally {
      setIsDownloading(false);
    }
  };

  let imageCount = 0;

  if (!content && !isGenerating) {
    return (
      <div className="h-full flex flex-col items-center justify-center bg-white text-slate-400 p-8 text-center border-l border-brand-200 select-none">
        <BookOpen className="w-20 h-20 mb-6 opacity-30 text-slate-900" />
        <h3 className="text-2xl font-serif font-bold mb-3 text-slate-800">Ebook Preview</h3>
        <p className="max-w-xs text-base text-slate-600">Your professional ebook will appear here.</p>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-slate-50 border-l border-brand-200">
      <div className="h-16 bg-white border-b border-brand-200 flex items-center justify-between px-6 sticky top-0 z-20 shadow-sm print-hide select-none">
        <span className="font-serif font-bold text-slate-900 truncate max-w-[50%] text-lg">
          {topic || "Untitled Ebook"}
        </span>
        <div className="flex items-center gap-3">
             {isGenerating && (
                <div className="flex items-center gap-2 text-brand-700 text-xs font-bold animate-pulse bg-brand-50 px-3 py-1.5 rounded-full border border-brand-200">
                    <Loader2 className="w-3 h-3 animate-spin" />
                    WRITING...
                </div>
            )}
            <button 
                onClick={handleDownloadPDF}
                disabled={content.length < 100 || isDownloading}
                className="flex items-center gap-2 px-4 py-2 bg-brand-800 text-white rounded-lg hover:bg-brand-900 disabled:opacity-50 disabled:cursor-not-allowed transition-all font-bold text-sm shadow-md"
                title="Download PDF"
            >
                {isDownloading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" /> Creating PDF...
                  </>
                ) : (
                  <>
                    <Download className="w-4 h-4" /> Download PDF
                  </>
                )}
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth bg-slate-100/50 selection:bg-yellow-200 selection:text-brand-900">
        <div ref={containerRef} className="max-w-[210mm] mx-auto">
          {sections.map((section, secIdx) => {
            const isCoverPage = section.type === 'title_page';
            const isTOC = section.type === 'toc_page';

            // Fixed height for Cover/TOC/Author/Intro to ensure 1-page feel, Min height for content
            const heightClass = (isCoverPage || isTOC || section.type === 'author_page' || section.type === 'intro_page') 
               ? 'h-[297mm] overflow-hidden' 
               : 'min-h-[297mm]';

            return (
            <div 
              key={secIdx} 
              data-type={section.type}
              className={`pdf-section bg-white shadow-sm p-[20mm] rounded-sm text-slate-900 mb-8 ${heightClass} flex flex-col cursor-text relative ${isCoverPage ? 'justify-center items-center text-center' : ''}`}
            >
              {section.blocks.map((block) => {
                if (block.type === 'title') {
                  return (
                    <div key={block.id} className="text-center w-full">
                       <h1 className="text-6xl md:text-7xl font-serif font-black text-slate-900 mb-8 tracking-tight leading-tight uppercase">
                        {block.content}
                      </h1>
                      <div className="w-32 h-2 bg-brand-600 mx-auto mb-10"></div>
                    </div>
                  );
                }

                if (block.type === 'header_main') {
                    return (
                        <div key={block.id} className="mb-8 border-b-4 border-slate-100 pb-4">
                            <h2 className="text-4xl font-serif font-bold text-slate-900">{block.content}</h2>
                        </div>
                    );
                }

                if (block.type === 'header_chapter') {
                    return (
                        <div key={block.id} className="mb-8 pt-4">
                            <span className="text-brand-600 font-bold tracking-widest text-sm uppercase block mb-2">Chapter</span>
                            <h2 className="text-4xl font-serif font-bold text-slate-900 leading-tight">{block.content}</h2>
                        </div>
                    );
                }

                if (block.type === 'image') {
                  imageCount++;
                  const isCover = imageCount === 1;
                  return (
                    <div key={block.id} className={`${isCover ? 'w-full my-8 flex-1 flex items-center justify-center' : 'my-6'}`}>
                       <ImageRenderer 
                        prompt={block.content} 
                        isCover={isCover} 
                        className={isCover ? "aspect-[2/3] object-cover shadow-2xl w-full max-w-lg mx-auto h-auto" : ""}
                       />
                    </div>
                  );
                }

                if (block.type === 'text') {
                  return (
                    <div key={block.id} className={`prose prose-slate font-serif text-slate-900 max-w-none w-full ${isTOC ? 'prose-lg leading-snug' : 'prose-lg'}`}>
                        {renderText(block.content, isTOC)}
                    </div>
                  );
                }
                return null;
              })}

              {!isCoverPage && (
                 <div className="absolute bottom-8 left-0 w-full text-center text-slate-300 text-xs select-none">
                    Page {secIdx + 1}
                 </div>
              )}
            </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

