    if (aiStudio && aiStudio.openSelectKey) {
        try {
            await aiStudio.openSelectKey();
            if (onUpdateApiKey) onUpdateApiKey();
        } catch (error) {
            console.error("Failed to select API key", error);
        }
    } else {
        alert("API Key selection is not supported in this environment.");
    }
  };

  return (
    <div className="flex flex-col h-full bg-white border-r border-brand-200">
      <div className="p-6 border-b border-brand-100 flex items-center justify-between bg-brand-50/50">
        <div className="flex items-center gap-3">
          <div className="bg-brand-800 p-2 rounded-lg text-white">
            <Sparkles className="w-5 h-5" />
