// Queue system to prevent Rate Limit (429) errors during image generation bursts
class RequestQueue {
  private queue: (() => Promise<void>)[] = [];
  private isProcessing = false;
  // 15s delay to be safe
  private delayMs = 15000; 

  enqueue<T>(task: () => Promise<T>): Promise<T> {
    return new Promise((resolve, reject) => {
      this.queue.push(async () => {
        try {
          const result = await task();
          resolve(result);
        } catch (err) {
          reject(err);
        }
      });
      this.process();
    });
  }

  private async process() {
    if (this.isProcessing) return;
    this.isProcessing = true;

    while (this.queue.length > 0) {
      const task = this.queue.shift();
      if (task) {
        await task();
        if (this.queue.length > 0) {
          // Wait before processing the next item
          await new Promise(resolve => setTimeout(resolve, this.delayMs));
        }
      }
    }
    this.isProcessing = false;
  }
}

const imageQueue = new RequestQueue();

// Helper to wait
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const getFallbackImage = (prompt: string) => `https://picsum.photos/seed/${encodeURIComponent(prompt.substring(0, 50))}/800/450`;

export const generateEbookImage = async (prompt: string): Promise<string> => {
  // If we already know the quota is exhausted for this session, fail fast to fallback.
  if (isImageQuotaExhausted) {
    return getFallbackImage(prompt);
  }

  // Enqueue the request
  return imageQueue.enqueue(async () => {
    // Double check inside the queue execution in case it was set while waiting
    if (isImageQuotaExhausted) {
        return getFallbackImage(prompt);
    }

    let attempts = 0;
    const maxAttempts = 3; 

    while (attempts < maxAttempts) {
      try {
        attempts++;

        // Smart Prompt Enhancement - Force styles based on keywords
        let finalPrompt = prompt;
        const lowerPrompt = prompt.toLowerCase();

        if (lowerPrompt.includes('cover:')) {
           finalPrompt = "3D Book Mockup, Hardcover book standing upright on a clean white surface, front view, highly detailed, 8k resolution, cinematic lighting, professional product photography, " + prompt.replace('COVER:', '');
        } else if (lowerPrompt.includes('diagram:') || lowerPrompt.includes('infographic') || lowerPrompt.includes('timeline') || lowerPrompt.includes('chart')) {
           finalPrompt = "Flat vector infographic, corporate memphis style, clean lines, white background, educational diagram, high quality, " + prompt.replace('DIAGRAM:', '');
        } else if (lowerPrompt.includes('author:')) {
           finalPrompt = "Professional headshot portrait, studio lighting, " + prompt.replace('AUTHOR:', '');
        } else {
           // Default fallback style
           finalPrompt = "High quality professional illustration, flat vector style, " + prompt;
        }

        // Using gemini-2.5-flash-image
        const response = await getAi().models.generateContent({
          model: 'gemini-2.5-flash-image',
          contents: {
            parts: [{ text: finalPrompt }]
          },
          config: {}
        });

        for (const part of response.candidates?.[0]?.content?.parts || []) {
          if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
          }
        }

        console.warn("Gemini returned no image data for prompt:", prompt);
        break; // Break if we get a valid response object but no data (unlikely to fix with retry)

      } catch (error: any) {
        const isRateLimit = error?.status === 429 || error?.code === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');
        const isServerError = error?.status === 500 || error?.status === 503 || error?.code === 500 || error?.message?.includes('500') || error?.message?.includes('Rpc failed') || error?.message?.includes('xhr error');

        if (isRateLimit) {
          if (attempts >= maxAttempts) {
             isImageQuotaExhausted = true;
             console.warn(`Quota exhausted. Switching to fallback.`);
             return getFallbackImage(prompt);
          }
          const waitTime = attempts * 10000;
          console.warn(`Rate limit. Waiting ${waitTime}ms...`);
          await wait(waitTime); 
          continue;
        }

        if (isServerError) {
             console.warn(`Server/Network error (Attempt ${attempts}). Retrying...`);
             await wait(3000); // Short wait for network glitch
             if (attempts >= maxAttempts) break;
             continue;
        }

        // Log other errors and break to fallback
        console.error(`Image generation attempt ${attempts} failed:`, error);
        break; 
      }
    }

    // Fallback if all attempts fail
    return getFallbackImage(prompt);
  });
};

