export const generateEbookImage = async (prompt: string): Promise<string> => {
  // If we already know the quota is exhausted for this session, fail fast to fallback.
  if (isImageQuotaExhausted) {
    console.log("Skipping generation due to quota exhaustion:", prompt);
    return getFallbackImage(prompt);
  }

  // Enqueue the request
  return imageQueue.enqueue(async () => {
    // Double check inside the queue execution in case it was set while waiting
    if (isImageQuotaExhausted) {
        return getFallbackImage(prompt);
    }

    let attempts = 0;
    const maxAttempts = 2; // Reduced attempts to avoid wasting time if blocked

    while (attempts < maxAttempts) {
      try {
        attempts++;

        // Smart Prompt Enhancement - Force styles based on keywords
        let finalPrompt = prompt;
        const lowerPrompt = prompt.toLowerCase();

        if (lowerPrompt.includes('cover:')) {
           finalPrompt = "3D Book Mockup, Hardcover book standing upright on a clean white surface, front view, highly detailed, 8k resolution, cinematic lighting, professional product photography, " + prompt.replace('COVER:', '');
        } else if (lowerPrompt.includes('diagram:') || lowerPrompt.includes('infographic') || lowerPrompt.includes('timeline') || lowerPrompt.includes('chart')) {
           finalPrompt = "Flat vector infographic, corporate memphis style, clean lines, white background, educational diagram, high quality, " + prompt.replace('DIAGRAM:', '');
        } else if (lowerPrompt.includes('author:')) {
           finalPrompt = "Professional headshot portrait, studio lighting, " + prompt.replace('AUTHOR:', '');
        } else {
           // Default fallback style
           finalPrompt = "High quality professional illustration, flat vector style, " + prompt;
        }

        // Using gemini-2.5-flash-image
        const response = await getAi().models.generateContent({
          model: 'gemini-2.5-flash-image',
          contents: {
            parts: [{ text: finalPrompt }]
          },
          config: {}
        });

        for (const part of response.candidates?.[0]?.content?.parts || []) {
          if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
          }
        }

        console.warn("Gemini returned no image data for prompt:", prompt);
        break; 

      } catch (error: any) {
        // DETECT QUOTA ERRORS (429 / Resource Exhausted)
        const errorMessage = error?.message || '';
        const isQuotaError = errorMessage.includes('quota') || errorMessage.includes('429') || errorMessage.includes('RESOURCE_EXHAUSTED') || error?.status === 429;
        const isServerError = error?.status === 500 || error?.status === 503 || errorMessage.includes('500') || errorMessage.includes('Rpc failed');

        if (isQuotaError) {
             console.warn(`Quota Exceeded (Free Tier Limit). Switching to fallback images for remaining session.`);
             isImageQuotaExhausted = true; // CRITICAL: Stop further requests
             return getFallbackImage(prompt);
        }

        if (isServerError) {
             console.warn(`Server/Network error (Attempt ${attempts}). Retrying...`);
             await wait(3000); 
             if (attempts >= maxAttempts) break;
             continue;
        }

        console.error(`Image generation attempt ${attempts} failed:`, error);
        break; 
      }
    }

    // Fallback if all attempts fail
    return getFallbackImage(prompt);
  });
};

