let customApiKey = '';

// --- CIRCUIT BREAKER SYSTEM ---
// This prevents the app from spamming the API when the Free Tier limit is reached.
let isQuotaLocked = false;
let quotaResetTime = 0;

const checkCircuitBreaker = () => {
  if (isQuotaLocked) {
    const remaining = Math.ceil((quotaResetTime - Date.now()) / 1000);
    if (remaining > 0) {
      throw new Error(`QUOTA_COOLDOWN:${remaining}`);
    } else {
      isQuotaLocked = false; // Reset if time passed
    }
  }
};

const triggerCircuitBreaker = () => {
  if (!isQuotaLocked) {
    console.warn("⚠️ API QUOTA HIT! Pausing all AI requests for 60 seconds.");
    isQuotaLocked = true;
    quotaResetTime = Date.now() + 60000; // 60 seconds cooldown
  }
};

