// OpenAI/OpenRouter Tool Format
const OPENROUTER_TOOLS = [
  {
    type: "function",
    function: {
      name: "generate_ebook",
      description: "Triggers the generation of the ebook based on the collected details.",
      parameters: {
        type: "object",
        properties: {
          topic: { type: "string", description: "The main topic/title of the ebook" },
          authorName: { type: "string", description: "The name of the author." },
          language: { type: "string", enum: ["English", "Hindi", "Hinglish"], description: "The language." },
          details: { type: "string", description: "Detailed summary of audience, tone, and chapters." },
        },
        required: ["topic", "authorName", "language", "details"],
      },
    }
  },
  {
    type: "function",
    function: {
      name: "edit_ebook",
      description: "Edits the ebook content based on user instructions.",
      parameters: {
        type: "object",
        properties: {
          instruction: { type: "string", description: "The specific instruction for editing." },
        },
        required: ["instruction"],
      },
    }
  }
];

export const sendChatRequest = async (messages: any[]) => {
  // 1. Prepare Messages (Convert to OpenAI format if needed)
  const conversation = messages.map(m => ({
    role: m.role === 'model' ? 'assistant' : 'user',
    content: m.text
  }));

  // Add System Instruction at the start
  conversation.unshift({
    role: 'system',
    content: "You are a friendly Ebook Publishing Assistant. \n\n1. Ask the user what topic they want to write about.\n2. Ask for the **Author Name**.\n3. Ask for Language.\n4. Once you have details, call `generate_ebook`.\n5. If the user wants to change anything later (text, images, author), call `edit_ebook`."
  });

  // 2. Try OpenRouter if Key exists
  if (openRouterApiKey) {
    try {
      const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${openRouterApiKey}`,
          "Content-Type": "application/json",
          "HTTP-Referer": "https://probook-ai.com", // Optional, for OpenRouter rankings
        },
        body: JSON.stringify({
          model: "google/gemini-2.0-flash-001", // Reliable, fast, usually free/cheap
          messages: conversation,
          tools: OPENROUTER_TOOLS,
        })
      });

      if (!response.ok) {
         const err = await response.json();
         throw new Error(err.error?.message || "OpenRouter Error");
      }

      const data = await response.json();
      const choice = data.choices[0];

      // Handle Tool Calls
      if (choice.message.tool_calls) {
        return {
          text: choice.message.content, // Sometimes null if strictly calling tool
          toolCalls: choice.message.tool_calls.map((tc: any) => ({
             name: tc.function.name,
             args: JSON.parse(tc.function.arguments)
          }))
        };
      }

      return { text: choice.message.content || "" };

    } catch (error) {
      console.error("OpenRouter Failed, falling back to Gemini if available", error);
      // Fallthrough to Gemini
    }
  }

  // 3. Fallback to Gemini (Direct SDK)
  // We need to reconstruct history for Gemini SDK
  const geminiChat = getGeminiClient().chats.create({
    model: 'gemini-2.5-flash',
    config: {
      systemInstruction: conversation[0].content, // Use the same system instruction
      tools: [{ functionDeclarations: OPENROUTER_TOOLS.map(t => ({ ...t.function, parameters: { ...t.function.parameters, type: "OBJECT" } as any })) }], // Convert to Gemini Tool format
    }
  });

  // Replay history (minus system)
  // Note: This is a stateless call simulation for compatibility. 
  // In a real app, we might keep the chat object alive, but here we just send the last message with history context if we were using `history`. 
  // For simplicity in this fallback, we just send the full context as "history" isn't fully supported in this stateless refactor without mapping.
  // We'll just send the LAST message and hope the context is enough or rely on the user providing info.
  // ACTUALLY: The best way is to just send the last message.

  const lastMsg = conversation[conversation.length - 1];
  const response = await geminiChat.sendMessage({ message: lastMsg.content });

  const functionCalls = response.functionCalls;
  if (functionCalls && functionCalls.length > 0) {
      return {
          text: response.text,
          toolCalls: functionCalls.map(fc => ({ name: fc.name, args: fc.args }))
      };
  }

  return { text: response.text };
};

export const streamEbookContent = async (
  topic: string,
  details: string,
  language: string,
  authorName: string,
  onChunk: (text: string) => void,
  currentContent?: string
) => {
  let prompt = '';

  if (currentContent) {
      // EDIT MODE
      prompt = `
      Task: REWRITE the ebook with the following changes.
      Change Instruction: ${details}
      Original Topic: ${topic}
      Original Author: ${authorName}
      Language: ${language}

      Requirements:
      1. Keep the same structure ([EBOOK TITLE], [TABLE OF CONTENTS], etc).
      2. Apply the user's change strictly.
      3. Output the WHOLE book again.
      `;
    } else {
      // CREATE MODE
      prompt = `
      Task: Write a complete, premium ebook.
      Topic: ${topic}
      Author: ${authorName}
      Language: ${language}
      Details: ${details}

      Structure Checklist:
      1. Cover Page (Title + Image)
      2. Table of Contents (ONE PAGE ONLY)
      3. Author Page (ONE PAGE ONLY)
      4. Introduction (ONE PAGE ONLY)
      5. Minimum 5 Chapters (Detailed)
      6. Conclusion
      `;
    }

  // A. Try OpenRouter Streaming
  if (openRouterApiKey) {
    try {
      const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${openRouterApiKey}`,
          "Content-Type": "application/json",
          "HTTP-Referer": "https://probook-ai.com",
        },
        body: JSON.stringify({
          model: "google/gemini-2.0-flash-001", 
          messages: [
            { role: "system", content: EBOOK_CREATOR_SYSTEM_INSTRUCTION },
            { role: "user", content: prompt }
          ],
          stream: true
        })
      });

      if (!response.body) throw new Error("No response body");
      const reader = response.body.getReader();
      const decoder = new TextDecoder("utf-8");

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split('\n');

        for (const line of lines) {
            if (line.startsWith('data: ') && line !== 'data: [DONE]') {
                try {
                    const json = JSON.parse(line.substring(6));
                    const content = json.choices[0]?.delta?.content;
                    if (content) onChunk(content);
                } catch (e) {
                    // Ignore parse errors for partial chunks
                }
            }
        }
      }
      return;
    } catch (e) {
       console.error("OpenRouter Stream Error", e);
       onChunk("\n[Switching to Backup Provider...]\n");
       // Fallthrough
    }
  }

  // B. Fallback to Gemini SDK Streaming
  try {
    const response = await getGeminiClient().models.generateContentStream({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: EBOOK_CREATOR_SYSTEM_INSTRUCTION,
        temperature: 0.7,
      }
    });

    for await (const chunk of response) {
      if (chunk.text) {
        onChunk(chunk.text);
      }
    }
  } catch (error: any) {
    onChunk(`\n\n**[SYSTEM ERROR]**\n\n${error.message}`);
  }
};

// --- IMAGE GENERATION (GEMINI ONLY) ---
class RequestQueue {
  private queue: (() => Promise<void>)[] = [];
  private isProcessing = false;
  private delayMs = 12000;

  enqueue<T>(task: () => Promise<T>): Promise<T> {
    return new Promise((resolve, reject) => {
      this.queue.push(async () => {
        try {
          const result = await task();
          resolve(result);
        } catch (err) {
          reject(err);
        }
      });
      this.process();
    });
  }

  private async process() {
    if (this.isProcessing) return;
    this.isProcessing = true;
    while (this.queue.length > 0) {
      const task = this.queue.shift();
      if (task) {
        if (isQuotaLocked) {
           await new Promise(resolve => setTimeout(resolve, 5000));
           this.queue.unshift(task!);
           continue;
        }
        await task();
        if (this.queue.length > 0) {
          await new Promise(resolve => setTimeout(resolve, this.delayMs));
        }
      }
    }
    this.isProcessing = false;
  }
}

const imageQueue = new RequestQueue();
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
const getFallbackImage = (prompt: string) => `https://placehold.co/800x450/EEE/31343C?text=${encodeURIComponent(prompt.substring(0, 20))}`;

export const generateEbookImage = async (prompt: string): Promise<string> => {
  try {
     checkCircuitBreaker();
  } catch (e) {
     return getFallbackImage(prompt);
  }

  return imageQueue.enqueue(async () => {
    if (isQuotaLocked) return getFallbackImage(prompt);

    let attempts = 0;
    const maxAttempts = 2; 

    while (attempts < maxAttempts) {
      try {
        attempts++;
        let finalPrompt = prompt;
        const lowerPrompt = prompt.toLowerCase();

        // STRICT STYLE CONTROL - NO NATURE
        if (lowerPrompt.includes('cover:')) {
           finalPrompt = "3D Hardcover Book Mockup, standing upright on white surface, studio lighting, high detail, product photography, " + prompt.replace('COVER:', '');
        } else if (lowerPrompt.includes('diagram:') || lowerPrompt.includes('infographic') || lowerPrompt.includes('chart')) {
           finalPrompt = "Flat vector infographic, corporate memphis style, clean white background, educational diagram, " + prompt.replace('DIAGRAM:', '') + ", NO nature, NO realistic photos, vector art only.";
        } else if (lowerPrompt.includes('author:')) {
           finalPrompt = "Professional headshot portrait, studio lighting, neutral background, " + prompt.replace('AUTHOR:', '');
        } else {
           finalPrompt = "Modern vector illustration, flat design, white background, business concept, " + prompt + ", NO nature, NO forests.";
        }

        const response = await getGeminiClient().models.generateContent({
          model: 'gemini-2.5-flash-image',
          contents: { parts: [{ text: finalPrompt }] },
        });

        for (const part of response.candidates?.[0]?.content?.parts || []) {
          if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
          }
        }
        break; 

      } catch (error: any) {
        const errorMessage = error?.message || '';
        const isQuotaError = errorMessage.includes('quota') || errorMessage.includes('429') || errorMessage.includes('RESOURCE_EXHAUSTED');
        const isServerError = error?.status === 500 || error?.status === 503;

        if (isQuotaError) {
             console.warn(`Gemini Image Quota Exceeded. Triggering Circuit Breaker.`);
             triggerCircuitBreaker();
             return getFallbackImage(prompt);
        }

        if (isServerError) {
             await wait(3000); 
             if (attempts >= maxAttempts) break;
             continue;
        }
        break; 
      }
    }
    return getFallbackImage(prompt);
  });
};

