import React, { useState } from 'react';
import { streamEbookContent, sendChatRequest, setApiKeys } from './services/gemini';
import { EbookReader } from './components/EbookReader';
import { ChatInterface } from './components/ChatInterface';

interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

const App = () => {
  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isSending, setIsSending] = useState(false);

  // Ebook State
  const [ebookContent, setEbookContent] = useState('');
  const [isGeneratingEbook, setIsGeneratingEbook] = useState(false);
  const [currentTopic, setCurrentTopic] = useState('');
  const [currentAuthor, setCurrentAuthor] = useState('');

  const handleManualApiKeys = (openRouter: string, gemini: string) => {
    setApiKeys(openRouter, gemini);
    setMessages(prev => [...prev, { role: 'model', text: "Dual API Keys updated! I'm ready to write with OpenRouter and draw with Gemini." }]);
  };

  const handleSendMessage = async (text: string) => {
    // 1. Optimistic Update
    const newHistory = [...messages, { role: 'user', text } as ChatMessage];
    setMessages(newHistory);
    setIsSending(true);

    try {
      // 2. Send to Unified Service (OpenRouter or Gemini)
      const response = await sendChatRequest(newHistory);

      // 3. Handle Function Calls
      if (response.toolCalls && response.toolCalls.length > 0) {
        const call = response.toolCalls[0];

        if (call.name === 'generate_ebook') {
          const { topic, details, language, authorName } = call.args;

          const selectedLang = language || "English";
          const selectedAuthor = authorName || "Unknown Author";

          setCurrentTopic(topic);
          setCurrentAuthor(selectedAuthor);

          setMessages(prev => [...prev, { 
            role: 'model', 
            text: `Starting your ${selectedLang} ebook on "${topic}" by ${selectedAuthor} using our high-performance engine...` 
          }]);

          setIsGeneratingEbook(true);
          setEbookContent(''); // Clear previous if any

          // Start Streaming Ebook
          await streamEbookContent(topic, details, selectedLang, selectedAuthor, (chunk) => {
            setEbookContent(prev => prev + chunk);
          });

          setIsGeneratingEbook(false);
          setMessages(prev => [...prev, { 
            role: 'model', 
            text: "Done! You can now download the complete PDF with visuals." 
          }]);
        }
        else if (call.name === 'edit_ebook') {
            const { instruction } = call.args;

            if (!ebookContent) {
                setMessages(prev => [...prev, { 
                    role: 'model', 
                    text: "I can't edit an ebook that hasn't been created yet. What would you like to write about first?" 
                }]);
                setIsSending(false);
                return;
            }

            setMessages(prev => [...prev, { 
                role: 'model', 
                text: `Refining the content: "${instruction}"...` 
            }]);

            setIsGeneratingEbook(true);
            const prevContent = ebookContent;
            setEbookContent(''); // Clear for rewrite

            // Stream Edited Ebook
            await streamEbookContent(
                currentTopic, 
                instruction, 
                "English", 
                currentAuthor, 
                (chunk) => {
                   setEbookContent(prev => prev + chunk);
                },
                prevContent 
            );

            setIsGeneratingEbook(false);
             setMessages(prev => [...prev, { 
                role: 'model', 
                text: "Updates applied successfully!" 
            }]);
        }

      } else {
        // Standard Text Response
        const responseText = response.text || "I didn't quite catch that.";
        setMessages(prev => [...prev, { role: 'model', text: responseText }]);
      }
    } catch (error) {
      console.error("Chat error:", error);
      setMessages(prev => [...prev, { role: 'model', text: "I encountered an error. Please check your API Keys in settings." }]);
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="flex h-screen overflow-hidden bg-brand-50">
      {/* Left Panel: Chat Interface */}
      <div className={`w-full md:w-[35%] lg:w-[30%] h-full flex flex-col z-10 shadow-xl ${isGeneratingEbook || ebookContent ? 'hidden md:flex' : 'flex'}`}>
        <ChatInterface 
          messages={messages} 
          onSendMessage={handleSendMessage}
          isSending={isSending}
          onManualApiKey={handleManualApiKeys}
        />
      </div>

      {/* Right Panel: Ebook Preview */}
      <div className={`w-full md:w-[65%] lg:w-[70%] h-full relative ${!isGeneratingEbook && !ebookContent ? 'hidden md:block' : 'block'}`}>
        <EbookReader 
          content={ebookContent} 
          isGenerating={isGeneratingEbook}
          topic={currentTopic}
        />
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";

// --- DUAL API KEYS ---
let textApiKey = '';
let imageApiKey = '';

export const setApiKeys = (textKey: string, imageKey: string) => {
  textApiKey = textKey;
  imageApiKey = imageKey;

  // Reset image breaker when keys update
  isImageQuotaLocked = false;
  imageQuotaResetTime = 0;
};

// --- HELPERS ---
const getTextAi = () => new GoogleGenAI({ apiKey: textApiKey || process.env.API_KEY || '' });
const getImageAi = () => new GoogleGenAI({ apiKey: imageApiKey || process.env.API_KEY || '' });

// --- CIRCUIT BREAKER (IMAGES) ---
// We primarily protect the Image API key as it hits limits faster
let isImageQuotaLocked = false;
let imageQuotaResetTime = 0;

const checkImageCircuitBreaker = () => {
  if (isImageQuotaLocked) {
    const remaining = Math.ceil((imageQuotaResetTime - Date.now()) / 1000);
    if (remaining > 0) {
      throw new Error(`QUOTA_COOLDOWN:${remaining}`);
    } else {
      isImageQuotaLocked = false; 
    }
  }
};

const triggerImageCircuitBreaker = () => {
  if (!isImageQuotaLocked) {
    console.warn("⚠️ IMAGE QUOTA HIT! Pausing images for 60 seconds.");
    isImageQuotaLocked = true;
    imageQuotaResetTime = Date.now() + 60000; 
  }
};

