  const [textKey, setTextKey] = useState('');
  const [imageKey, setImageKey] = useState('');

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && !isSending) {
      onSendMessage(input);
      setInput('');
    }
  };

  const handleKeysSave = () => {
    if (onManualApiKey) {
      // If user only provided one key, use it for both
      const tKey = textKey.trim();
      const iKey = imageKey.trim();

      const finalTextKey = tKey;
      const finalImageKey = iKey || tKey; // Fallback to text key if image key is empty

