              <h3 className="font-serif font-bold text-brand-900 flex items-center gap-2">
                <Key className="w-4 h-4" /> Gemini API Keys
              </h3>
              <button onClick={() => setIsSettingsOpen(false)} className="text-brand-400 hover:text-brand-800 transition-colors">
                <X className="w-5 h-5" />
