            </div>

            <div className="p-5 space-y-6">

              <div className="bg-blue-50 p-3 rounded-lg text-xs text-blue-800 mb-2">
                <strong>Tip:</strong> You can use the same key for both, or two different keys to double your quota.
              </div>

              {/* Text Generation Key */}
              <div className="space-y-2">
                <label className="text-xs font-bold text-brand-500 uppercase tracking-wider block flex items-center gap-2">
                  <FileText className="w-3 h-3" /> Text API Key (Gemini)
